@Composable
fun CommentItem(
 comment: Comment,
 postViewModel: PostViewModel,
 replies: List<Comment> = emptyList(),
 isShowingReplies: Boolean = false,
 profilePictureUrl: String? = null,
 onReplyClick: (Comment) -> Unit,
 userId: String? = null,
 navController: NavController? = null,
 onProfileClick: (() -> Unit)? = null
) {
 Card(
 modifier = Modifier
 .fillMaxWidth()
 .padding(horizontal = 16.dp, vertical = 4.dp),
 elevation = CardDefaults.cardElevation(defaultElevation = 1.dp)
 ) {
 Column(
 modifier = Modifier.padding(16.dp)
 ) {
 Row(
 verticalAlignment = Alignment.CenterVertically,
 ) {
 // Profile picture
 Box(
 modifier = Modifier
 .size(40.dp)
 .clip(CircleShape)
 .background(MaterialTheme.colorScheme.primary.copy(alpha = 0.2f))
 .clickable {
 if (onProfileClick != null) {
 onProfileClick()
 } else if (userId != null && navController != null) {
 Navigation.navigateToUserProfile(userId, navController)
 }
 }
 ) {
 if (profilePictureUrl != null) {
 AsyncImage(
 model = profilePictureUrl,
 contentDescription = "Profile picture",
 contentScale = ContentScale.Crop,
 modifier = Modifier.fillMaxWidth()
 )
 } else {
 // User initial as placeholder - use first letter of display name
 Icon(
 imageVector = Icons.Default.Person,
 contentDescription = null,
 modifier = Modifier.align(Alignment.Center)
 )
 }
 }

 Spacer(modifier = Modifier.width(8.dp))

 // Author name - use display name directly
 Text(
 text = comment.userDisplayName,
 fontSize = 20.sp,
 fontWeight = FontWeight.Bold,
 color = LocalCustomColors.current.textPrimary,
 modifier = Modifier
 .padding(top = 4.dp, start = 2.dp)
 .clickable {
 if (onProfileClick != null) {
 onProfileClick()
 } else if (userId != null && navController != null) {
 Navigation.navigateToUserProfile(userId, navController)
 }
 }
 )
 }

 Spacer(modifier = Modifier.height(8.dp))

 Text(
 text = comment.text,
 fontSize = 20.sp,
 color = LocalCustomColors.current.textPrimary,
 modifier = Modifier.padding(horizontal = 4.dp, vertical = 8.dp)
 )

 // Show image if available
 if (comment.imageUrl != null) {
 Spacer(modifier = Modifier.height(8.dp))
 AsyncImage(
 model = comment.imageUrl,
 contentDescription = "Comment image",
 modifier = Modifier
 .fillMaxWidth()
 .height(200.dp)
 .padding(12.dp),
 contentScale = ContentScale.Crop
 )
 }

 Spacer(modifier = Modifier.height(8.dp))

 HorizontalDivider(
 modifier = Modifier.padding(horizontal = 8.dp),
 color = Color.LightGray,
 thickness = 0.5.dp
 )

 // Action buttons row (like, reply, etc.)
 Row(
 modifier = Modifier
 .fillMaxWidth()
 .padding(horizontal = 4.dp, vertical = 4.dp),
 verticalAlignment = Alignment.CenterVertically,
 horizontalArrangement = Arrangement.SpaceAround
 ) {
 // Like button
 Box(
 modifier = Modifier
 .weight(1f, fill = false)
 .padding(vertical = 8.dp, horizontal = 8.dp)
 .clickable {
 postViewModel.toggleCommentLike(comment.id)
 },
 contentAlignment = Alignment.CenterStart
 ) {
 Row(
 verticalAlignment = Alignment.CenterVertically
 ) {
 Icon(
 painter = painterResource(if (comment.isLikedByCurrentUser) R.drawable.ic_like_filled else R.drawable.ic_like),
 contentDescription = "Like",
 tint = if (comment.isLikedByCurrentUser)
 Color(0xFFE91E63) else Color.Gray,
 modifier = Modifier.size(24.dp)
 )
 Spacer(modifier = Modifier.width(4.dp))
 Text(
 text = "${comment.likeCount}",
 fontSize = 16.sp,
 color = if (comment.isLikedByCurrentUser)
 LocalCustomColors.current.textIsLiked else LocalCustomColors.current.textPrimary
 )
 }
 }

 // Reply button
 Box(
 modifier = Modifier
 .weight(1f, fill = false)
 .padding(vertical = 8.dp, horizontal = 8.dp)
 .clickable {
 onReplyClick(comment)
 },
 contentAlignment = Alignment.CenterStart
 ) {
 Row(
 verticalAlignment = Alignment.CenterVertically
 ) {
 Image(
 painter = painterResource(R.drawable.ic_comment),
 contentDescription = "Comment icon",
 modifier = Modifier
 .size(24.dp)
 .padding(end = 4.dp)
 )

 Text(
 text = "${comment.replyCount}",
 fontSize = 16.sp,
 color = LocalCustomColors.current.textPrimary,
 modifier = Modifier
 )
 }
 }
 }

 // Display replies if expanded
// if (isShowingReplies && replies.isNotEmpty()) {
// Column(
// modifier = Modifier
// .fillMaxWidth()
// .padding(start = 16.dp, top = 8.dp)
// ) {
// replies.forEach { reply ->
// ReplyItem(
// reply = reply,
// postViewModel = postViewModel,
// onReplyClick = onReplyClick
// )
// }
// }
// }
 }
 }
