+ fun loadReplies(commentId: String) {
+ viewModelScope.launch {
+ try {
+ val replies = repository.getRepliesForComment(commentId)
+
+ _uiState.update { currentState ->
+ val updatedReplies = currentState.repliesState + (commentId to replies)
+ currentState.copy(repliesState = updatedReplies)
+ }
+ } catch (e: Exception) {
+ Log.e("PostViewModel", "Error loading replies", e)
+ }
+ }
+ }
+
+ // Load nested replies (replies to replies)
+ fun loadNestedReplies(replyId: String) {
+ viewModelScope.launch {
+ try {
+ val nestedReplies = repository.getRepliesForComment(replyId)
+
+ _uiState.update { currentState ->
+ val updatedNestedReplies =
+ currentState.nestedRepliesState + (replyId to nestedReplies)
+ currentState.copy(nestedRepliesState = updatedNestedReplies)
+ }
+
+ Log.d(
+ "PostViewModel",
+ "Loaded ${nestedReplies.size} nested replies for comment $replyId"
+ )
+ } catch (e: Exception) {
+ Log.e("PostViewModel", "Error loading nested replies", e)
+ }
+ }
+ }
+
+ fun setReplyingTo(comment: Comment) {
+ _uiState.update { it.copy(replyingToState = comment) }
+ }
+
+ fun cancelReply() {
+ _uiState.update { it.copy(replyingToState = null) }
+ }
+
+ // Add a nested reply (reply to a reply)
+ fun addNestedReply(
+ context: Context,
+ parentReplyId: String,
+ text: String,
+ mediaUri: Uri?,
+ isVideo: Boolean = false
+ ) {
+ viewModelScope.launch {
+ _uiState.update { it.copy(uploadingMedia = true) }
+
+ try {
+ var mediaUrl: String? = null
+ if (mediaUri != null) {
+ when (val uploadResult = uploadMedia(context, mediaUri, isVideo)) {
+ is MediaUploadState.Success -> {
+ mediaUrl = uploadResult.mediaUrl
+ Log.d("PostViewModel", "Media uploaded: $mediaUrl")
+ }
+
+ is MediaUploadState.Error -> {
+ throw Exception("Failed to upload media: ${uploadResult.message}")
+ }
+
+ else -> {
+ throw Exception("Unexpected upload state")
+ }
+ }
+ }
+
+ val nestedReply =
+ repository.addReplyWithMediaUrl(parentReplyId, text, mediaUrl, isVideo)
+ cloudinaryUploader.resetState()
+
+ _uiState.update { currentState ->
+ // Update the reply count on the parent reply
+ val updatedRepliesState = updateNestedRepliesInUIState(
+ currentState.repliesState,
+ parentReplyId
+ )
+
+ // Add the new nested reply to the nestedRepliesState
+ val currentNestedReplies = currentState.nestedRepliesState
+ val replyNestedReplies = currentNestedReplies[parentReplyId] ?: emptyList()
+ val updatedNestedReplies =
+ currentNestedReplies + mapOf(parentReplyId to (replyNestedReplies + nestedReply))
+
+ currentState.copy(
+ repliesState = updatedRepliesState,
+ nestedRepliesState = updatedNestedReplies,
+ replyingToState = null,
+ uploadingMedia = false
+ )
+ }
+ } catch (e: Exception) {
+ Log.e("PostViewModel", "Error adding nested reply", e)
+ _uiState.update { it.copy(uploadingMedia = false) }
+ }
+ }
+ }
+
+ // Update the reply count for a reply in all possible locations
+ private fun updateNestedRepliesInUIState(
+ repliesState: Map<String, List<Comment>>,
+ replyId: String
+ ): Map<String, List<Comment>> {
+ val updatedRepliesState = repliesState.mapValues { (_, replies) ->
+ replies.map { reply ->
+ if (reply.id == replyId) {
+ reply.copy(replyCount = reply.replyCount + 1)
+ } else {
+ reply
+ }
+ }
+ }
+ return updatedRepliesState
+ }
