 Box(
 modifier = Modifier
 .fillMaxWidth()
 .padding(16.dp),
 contentAlignment = Alignment.Center
 ) {
 CircularProgressIndicator()
 }
 }
 }
 is CommentsState.Success -> {
 val comments = uiState.commentsState.comments

 if (comments.isEmpty()) {
 item {
 Box(
 modifier = Modifier
 .fillMaxWidth()
 .padding(32.dp),
 contentAlignment = Alignment.Center
 ) {
 Text(stringResource(R.string.no_comments_yet))
 }
 }
 } else {
 items(comments) { comment ->
 val isShowingReplies =
 uiState.repliesState.containsKey(comment.id)
 val replies = uiState.repliesState[comment.id] ?: emptyList()

 CommentItem(
 comment = comment,
 postViewModel = postViewModel,
 profilePictureUrl = post.userProfilePicture,
 replies = replies,
 isShowingReplies = isShowingReplies,
 userId = comment.userId,
 navController = navController,
 onReplyClick = { clickedComment ->
 postViewModel.setReplyingTo(clickedComment)
 }
 )
 }
 }
 }
 is CommentsState.Error -> {
 item {
 Text(
 text = stringResource(
 R.string.error_loading_comments,
 uiState.commentsState.message
 ),
 color = Color.Red,
 modifier = Modifier.padding(16.dp)
 )
 }
 }
 null -> {
 item {
 Text(
 text = stringResource(R.string.loading_comments),
 modifier = Modifier.padding(16.dp)
 )
 }
 }
 }
 }

 // Comment input section - fixed at bottom
 Card(
 modifier = Modifier
 .align(Alignment.BottomCenter)
 .fillMaxWidth(),
 elevation = CardDefaults.cardElevation(defaultElevation = 4.dp)
 ) {
 Column(
 modifier = Modifier
 .fillMaxWidth()
 .padding(12.dp)
 ) {
 // Show who we're replying to, if applicable
 uiState.replyingToState?.let { comment ->
 Row(
 modifier = Modifier
 .fillMaxWidth()
 .padding(bottom = 8.dp),
 verticalAlignment = Alignment.CenterVertically
 ) {
 Text(
 text = stringResource(
 R.string.replying_to,
 comment.userDisplayName
 ),
 style = MaterialTheme.typography.bodySmall,
 color = MaterialTheme.colorScheme.primary,
 modifier = Modifier.weight(1f)
 )
 IconButton(
 onClick = { postViewModel.cancelReply() }
 ) {
 Icon(
 imageVector = Icons.Filled.Close,
 contentDescription = "Cancel reply"
 )
 }
 }
 }

 // Show selected image preview if any
 selectedImageUri?.let { uri ->
 Box(
 modifier = Modifier
 .fillMaxWidth()
 .height(120.dp)
 .padding(bottom = 8.dp)
 ) {
 if (isVideo) {
 VideoPlayer(
 videoUrl = uri.toString(),
 modifier = Modifier
 .fillMaxSize()
 .clip(RoundedCornerShape(8.dp))
 )
 } else {
 AsyncImage(
 model = uri,
 contentDescription = "Selected image",
 modifier = Modifier
 .fillMaxSize()
 .clip(RoundedCornerShape(8.dp)),
 contentScale = ContentScale.Crop
 )
 }

 // Close/remove image button
 Box(
 modifier = Modifier
 .padding(8.dp)
 .size(22.dp)
 .align(Alignment.TopEnd)
 .background(
 MaterialTheme.colorScheme.surfaceVariant.copy(
 alpha = 0.7f
 ),
 CircleShape
 )
 .clickable { selectedImageUri = null },
 contentAlignment = Alignment.Center
 ) {
 Icon(
 imageVector = Icons.Filled.Close,
 contentDescription = "Remove image",
 tint = MaterialTheme.colorScheme.onSurfaceVariant,
 modifier = Modifier.size(12.dp)
 )
 }
 }
 }

 // Show upload progress if uploading
 if (uiState.uploadingMedia) {
 Row(
 verticalAlignment = Alignment.CenterVertically,
 modifier = Modifier.fillMaxWidth()
 ) {
 CircularProgressIndicator(
 modifier = Modifier.size(16.dp),
 strokeWidth = 2.dp
 )
 Spacer(modifier = Modifier.width(8.dp))
 Text(
 stringResource(R.string.uploading),
 style = MaterialTheme.typography.bodySmall
 )
 }
 }

 Row(
 modifier = Modifier.fillMaxWidth(),
 verticalAlignment = Alignment.CenterVertically
 ) {
 OutlinedTextField(
 value = commentText,
 onValueChange = { commentText = it },
 modifier = Modifier.weight(1f),
 placeholder = {
 Text(
 if (uiState.replyingToState != null)
 stringResource(R.string.write_a_reply)
 else
 stringResource(R.string.add_a_comment)
 )
 },
 maxLines = 3
 )

 Spacer(modifier = Modifier.width(8.dp))

 // Image picker button
 IconButton(
 onClick = { mediaPickerLauncher.launch("*/*") }
 ) {
 Icon(
 imageVector = Icons.Filled.Add,
 contentDescription = "Attach media",
 tint = MaterialTheme.colorScheme.primary
 )
 }

 IconButton(
 onClick = {
 if (commentText.isNotBlank() || selectedImageUri != null) {
 val replyingToComment = uiState.replyingToState

 if (replyingToComment != null) {
 if (isReplyingToReply(replyingToComment)) {
 postViewModel.addNestedReply(
 context,
 replyingToComment.id,
 commentText,
 selectedImageUri,
 isVideo
 )
 } else {
 postViewModel.addReply(
 context,
 replyingToComment.id,
 commentText,
 selectedImageUri,
 isVideo
 )
 }
 } else {
 postViewModel.addComment(
 context,
 post.id,
 commentText,
 selectedImageUri,
 isVideo
 )
 }
 commentText = ""
 selectedImageUri = null
 keyboardController?.hide()
 focusManager.clearFocus()
 }
 }
 ) {
 Icon(
 imageVector = Icons.AutoMirrored.Filled.Send,
 contentDescription = if (uiState.replyingToState != null) "Send reply" else "Send comment",
 tint = if (commentText.isNotBlank() || selectedImageUri != null)
 MaterialTheme.colorScheme.primary
 else
 MaterialTheme.colorScheme.onSurface.copy(alpha = 0.4f)
 )
 }
 }
 }
 }
 }
 }
 is CurrentPostState.Error -> {
 Text(
 text = stringResource(R.string.error, uiState.currentPostState.message),
 color = Color.Red,
 modifier = Modifier
 .align(Alignment.Center)
 .padding(16.dp)
 )
 }
 CurrentPostState.NotSelected -> {
 Text(
 text = stringResource(R.string.no_post_selected),
 modifier = Modifier
 .align(Alignment.Center)
 .padding(16.dp)
 )
 }
 null -> {
 CircularProgressIndicator(
 modifier = Modifier.align(Alignment.Center)
 )
 }
 }
 }
 }
}

private fun isReplyingToReply(comment: Comment): Boolean {
 return comment.parentCommentId != null
}

