er: NavController? = null,\n postViewModel: PostViewModel = viewModel()\n) {\n val uiState = postViewModel.uiState.collectAsStateWithLifecycle().value\n\n val keyboardController = LocalSoftwareKeyboardController.current\n val focusManager = LocalFocusManager.current\n val context = LocalContext.current\n val scrollState = rememberLazyListState()\n var commentText by remember { mutableStateOf(\"\") }\n var selectedImageUri by remember { mutableStateOf<Uri?>(null) }\n var isVideo by remember { mutableStateOf(false) }\n\n@@ ... @@\n Scaffold(\n topBar = {\n TopAppBar(\n title = {\n Text(\n stringResource(R.string.post_details),\n color = LocalCustomColors.current.textPrimary\n )\n },\n navigationIcon = {\n IconButton(onClick = {\n postViewModel.clearCurrentPost()\n onBackClick()\n }) {\n Icon(\n imageVector = Icons.AutoMirrored.Filled.ArrowBack,\n contentDescription = \"Back\"\n )\n }\n },\n colors = TopAppBarDefaults.topAppBarColors(\n containerColor = LocalCustomColors.current.navBarsBackground\n ),\n )\n }\n ) { paddingValues ->\n\n@@ ... @@\n Scaffold(\n topBar = {\n TopAppBar(\n title = {\n Text(\n stringResource(R.string.post_details),\n color = LocalCustomColors.current.textPrimary\n )\n },\n navigationIcon = {\n IconButton(onClick = {\n postViewModel.clearCurrentPost()\n onBackClick()\n }) {\n Icon(\n imageVector = Icons.AutoMirrored.Filled.ArrowBack,\n contentDescription = \"Back\"\n )\n }\n },\n colors = TopAppBarDefaults.topAppBarColors(\n containerColor = LocalCustomColors.current.navBarsBackground\n ),\n )\n },\n // Place the comment input at the bottom of the screen\n bottomBar = {\n CommentInputBar(\n commentText = commentText,\n onCommentTextChange = { commentText = it },\n selectedImageUri = selectedImageUri,\n onSelectedImageUriChange = { selectedImageUri = it },\n isVideo = isVideo,\n onIsVideoChange = { isVideo = it },\n isUploading = uiState.uploadingMedia,\n replyingToState = uiState.replyingToState,\n onCancelReply = { postViewModel.cancelReply() },\n onSendComment = {\n if (commentText.isNotBlank() || selectedImageUri != null) {\n val replyingToComment = uiState.replyingToState\n \n if (replyingToComment != null) {\n if (isReplyingToReply(replyingToComment)) {\n postViewModel.addNestedReply(\n context,\n replyingToComment.id,\n commentText,\n selectedImageUri,\n isVideo\n )\n } else {\n postViewModel.addReply(\n context,\n replyingToComment.id,\n commentText,\n selectedImageUri,\n isVideo\n )\n }\n } else {\n postViewModel.addComment(\n context,\n uiState.currentPostState.let {\n if (it is CurrentPostState.PostLoaded) it.post.id else \"\"\n },\n commentText,\n selectedImageUri,\n isVideo\n )\n }\n commentText = \"\"\n selectedImageUri = null\n keyboardController?.hide()\n focusManager.clearFocus()\n }\n }\n )\n }\n ) { paddingValues ->\n\n@@ ... @@\n Box(modifier = Modifier.fillMaxSize()) {\n // Main content - scrollable\n LazyColumn(\n state = scrollState,\n modifier = Modifier\n .fillMaxSize()\n .padding(bottom = bottomPadding)\n ) {\n\n@@ ... @@\n Box(modifier = Modifier.fillMaxSize()) {\n // Main content - scrollable\n LazyColumn(\n state = scrollState,\n modifier = Modifier\n .fillMaxSize()\n .padding(paddingValues) // Use the padding values from Scaffold\n ) {\n\n@@ ... @@\n // Comment input section - fixed at bottom\n Card(\n modifier = Modifier\n .align(Alignment.BottomCenter)\n .fillMaxWidth()\n .imePadding() // Ensures the input box stays above the keyboard\n .navigationBarsPadding(), // Add padding for navigation bar\n elevation = CardDefaults.cardElevation(defaultElevation = 4.dp),\n colors = CardDefaults.cardColors(\n containerColor = MaterialTheme.colorScheme.surface\n )\n ) {\n Column(\n modifier = Modifier\n .fillMaxWidth()\n .padding(12.dp)\n ) {\n\n@@ ... @@\n }\n }\n }\n is CurrentPostState.Error -> {"}"}}]},{"role":"tool","name":"edit_file","tool_call_id":"toolu_bdrk_01WkX5w8YbxYcKX3P1rKfPq2","content":"The apply model made the following changes to the file:

