 onProfileClick()
 } else if (userId != null && navController != null) {
 Navigation.navigateToUserProfile(userId, navController)
 }
 }
 ) {
 if (profilePictureUrl != null) {
 AsyncImage(
 model = profilePictureUrl,
 contentDescription = "Profile picture",
 contentScale = ContentScale.Crop,
 modifier = Modifier.fillMaxWidth()
 )
 } else {
 // User initial as placeholder - use first letter of display name
 Icon(
 imageVector = Icons.Default.Person,
 contentDescription = null,
 modifier = Modifier.align(Alignment.Center)
 )
 }
 }

 Spacer(modifier = Modifier.width(8.dp))

 // Author name - also clickable to go to profile
 Text(
 text = authorName,
 fontSize = 20.sp,
 fontWeight = FontWeight.Bold,
 color = LocalCustomColors.current.textPrimary,
 modifier = Modifier
 .padding(top = 4.dp, start = 2.dp)
 .clickable {
 if (onProfileClick != null) {
 onProfileClick()
 } else if (userId != null && navController != null) {
 Navigation.navigateToUserProfile(userId, navController)
 }
 }
 )
 }

 // Post content
 Text(
 text = content,
 fontSize = 20.sp,
 color = LocalCustomColors.current.textPrimary,
 modifier = Modifier.padding(horizontal = 16.dp, vertical = 8.dp)
 )

 // Display image or video if available
 if (hasVideo && videoUrl != null) {
 var showFullScreenVideo by remember { mutableStateOf(false) }

 VideoPlayer(
 videoUrl = videoUrl,
 modifier = Modifier
 .fillMaxWidth()
 .height(220.dp)
 .padding(12.dp)
 .clip(RoundedCornerShape(16.dp))
 .clickable { showFullScreenVideo = true }
 )

 if (showFullScreenVideo) {
 MediaViewerScreen(
 mediaUrl = videoUrl,
 isVideo = true,
 onDismiss = { showFullScreenVideo = false }
 )
 }
 } else if (imageUrl != null) {
 var showFullScreenImage by remember { mutableStateOf(false) }

 Box(
 modifier = Modifier
 .fillMaxWidth()
 .height(220.dp)
 .padding(bottom = 5.dp)
 .clickable { showFullScreenImage = true }
 ) {
 CircularProgressIndicator(
 modifier = Modifier
 .size(40.dp)
 .align(Alignment.Center)
 )

 AsyncImage(
 model = if (imageUrl.startsWith("content:") || imageUrl.startsWith("file:")) {
 Uri.parse(imageUrl)
 } else {
 imageUrl
 },
 contentDescription = "Post image",
 contentScale = ContentScale.Fit,
 modifier = Modifier
 .fillMaxSize()
 .padding(12.dp)
 .clip(RoundedCornerShape(16.dp)),
 error = painterResource(id = R.drawable.ic_error_image),
 placeholder = painterResource(id = R.drawable.ic_error_image),
 onLoading = {
 android.util.Log.d("PostItemDetailed", "Loading image: $imageUrl")
 },
 onError = {
 android.util.Log.e(
 "PostItemDetailed",
 "Error loading image: $imageUrl, error: $it"
 )
 },
 onSuccess = {
 android.util.Log.d(
 "PostItemDetailed",
 "Successfully loaded image: $imageUrl"
 )
 }
 )
 }

 // Show full screen image viewer when clicked
 if (showFullScreenImage) {
 MediaViewerScreen(
 mediaUrl = imageUrl,
 isVideo = false,
 onDismiss = { showFullScreenImage = false }
 )
 }
 }

 HorizontalDivider(
 modifier = Modifier.padding(horizontal = 8.dp),
 color = Color.LightGray,
 thickness = 0.5.dp
 )

 // Action buttons row
 Row(
 modifier = Modifier
 .fillMaxWidth()
 .padding(horizontal = 4.dp, vertical = 4.dp),
 verticalAlignment = Alignment.CenterVertically,
 horizontalArrangement = androidx.compose.foundation.layout.Arrangement.SpaceAround
 ) {
