 }
 }

 val postId = postsCollection.document().id
 val post = Post(
 id = postId,
 userId = currentUser.uid,
 userDisplayName = userDisplayName,
 userProfilePicture = userProfilePicture,
 text = text,
 imageUrl = imageUrl,
 createdAt = Timestamp.now()
 )

 postsCollection.document(postId).set(post).await()
 post
 }

