package com.example.kiendatn2.ui.search

import androidx.compose.foundation.layout.*
import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.lazy.items
import androidx.compose.foundation.text.KeyboardActions
import androidx.compose.foundation.text.KeyboardOptions
import androidx.compose.material.icons.Icons
import androidx.compose.material.icons.filled.Clear
import androidx.compose.material.icons.filled.Delete
import androidx.compose.material.icons.filled.Search
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.input.key.Key.Companion.Delete
import androidx.compose.ui.res.stringResource
import androidx.compose.ui.text.input.ImeAction
import androidx.compose.ui.unit.dp
import androidx.lifecycle.compose.collectAsStateWithLifecycle
import androidx.lifecycle.viewmodel.compose.viewModel
import androidx.navigation.NavController
import com.example.kiendatn2.R
import com.example.kiendatn2.ui.post.PostItem
import com.example.kiendatn2.ui.post.PostViewModel
import com.example.kiendatn2.ui.theme.LocalCustomColors
import com.google.api.ResourceDescriptor.History

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun SearchScreen(
 viewModel: SearchViewModel = viewModel(),
 navController: NavController? = null,
 onNavigateToComments: (String) -> Unit = {},
 postViewModel: PostViewModel = viewModel()
) {
 val uiState = viewModel.uiState.collectAsStateWithLifecycle().value
 var searchQuery by remember { mutableStateOf("") }

 Column(
 modifier = Modifier
 .fillMaxSize()
 ) {
 Row(
 modifier = Modifier
 .fillMaxWidth()
 .padding(horizontal = 16.dp, vertical = 8.dp),
 verticalAlignment = Alignment.CenterVertically
 ) {
 OutlinedTextField(
 value = searchQuery,
 onValueChange = {
 searchQuery = it
 },
 placeholder = { Text(stringResource(R.string.search)) },
 leadingIcon = {
 Icon(
 imageVector = Icons.Filled.Search,
 contentDescription = "Search"
 )
 },
 trailingIcon = {
 if (searchQuery.isNotEmpty()) {
 IconButton(onClick = {
 searchQuery = ""
 viewModel.searchPosts("")
 }) {
 Icon(
 imageVector = Icons.Filled.Clear,
 contentDescription = stringResource(R.string.clear_search)
 )
 }
 }
 },
 singleLine = true,
 keyboardOptions = KeyboardOptions(imeAction = ImeAction.Search),
 keyboardActions = KeyboardActions(
 onSearch = {
 if (searchQuery.length >= 2) {
 viewModel.searchPosts(searchQuery)
 viewModel.saveSearchToHistory(searchQuery)
 }
 }
 ),
 modifier = Modifier
 .weight(1f)
 )

 Spacer(modifier = Modifier.width(8.dp))

 Button(
 onClick = {
 if (searchQuery.length >= 2) {
 viewModel.searchPosts(searchQuery)
 viewModel.saveSearchToHistory(searchQuery)
 }
 },
 colors = ButtonDefaults.buttonColors(
 containerColor = LocalCustomColors.current.secondaryBackground,
 ),
 ) {
 Text(text = stringResource(R.string.search), color = LocalCustomColors.current.textPrimary)
 }
 }

 Box(
 modifier = Modifier
 .fillMaxSize()
 .padding(8.dp)
 ) {
 when (val searchState = uiState.searchState) {
 is SearchState.Loading -> {
 Column {
 // Loading indicator
 Box(modifier = Modifier.weight(1f)) {
 CircularProgressIndicator(
 modifier = Modifier.align(Alignment.Center)
 )
 }

 // Show search history below loading indicator
 SearchHistorySection(
 searchHistory = uiState.searchHistory,
 onHistoryItemClick = { query ->
 searchQuery = query
 viewModel.searchPosts(query)
 },
 onDeleteHistoryItem = { historyId ->
 viewModel.deleteSearchHistoryItem(historyId)
 },
 onClearHistory = {
 viewModel.clearSearchHistory()
 }
 )
 }
 }

 is SearchState.Success -> {
 val posts = searchState.posts
 Column {
 // Show search results
 Box(modifier = Modifier.weight(1f)) {
 if (posts.isEmpty()) {
 Text(
 text = "No posts found",
 modifier = Modifier.align(Alignment.Center),
 color = LocalCustomColors.current.textPrimary
 )
 } else {
 LazyColumn {
 items(posts) { post ->
 PostItem(
 post = post,
 postViewModel = postViewModel,
 navController = navController
 )
 Spacer(modifier = Modifier.height(8.dp))
 }
 }
 }
 }

 // Show search history below results
 SearchHistorySection(
 searchHistory = uiState.searchHistory,
 onHistoryItemClick = { query ->
 searchQuery = query
 viewModel.searchPosts(query)
 },
 onDeleteHistoryItem = { historyId ->
 viewModel.deleteSearchHistoryItem(historyId)
 },
 onClearHistory = {
 viewModel.clearSearchHistory()
 }
 )
 }
 }

 is SearchState.Error -> {
 Column {
 // Error message
 Box(modifier = Modifier.weight(1f)) {
 Text(
 text = stringResource(R.string.error_prefix, searchState.message),
 color = MaterialTheme.colorScheme.error,
 modifier = Modifier.align(Alignment.Center)
 )
 }

 // Show search history below error message
 SearchHistorySection(
 searchHistory = uiState.searchHistory,
 onHistoryItemClick = { query ->
 searchQuery = query
 viewModel.searchPosts(query)
 },
 onDeleteHistoryItem = { historyId ->
 viewModel.deleteSearchHistoryItem(historyId)
 },
 onClearHistory = {
 viewModel.clearSearchHistory()
 }
 )
 }
 }

 is SearchState.Initial -> {
 if (searchQuery.isEmpty()) {
 // Show search history when no active search
 SearchHistorySection(
 searchHistory = uiState.searchHistory,
 onHistoryItemClick = { query ->
 searchQuery = query
 viewModel.searchPosts(query)
 },
 onDeleteHistoryItem = { historyId ->
 viewModel.deleteSearchHistoryItem(historyId)
 },
 onClearHistory = {
 viewModel.clearSearchHistory()
 }
 )
 } else {
 Text(
 text = stringResource(R.string.type_to_search),
 modifier = Modifier.align(Alignment.Center),
 color = LocalCustomColors.current.textPrimary
 )
 }
 }
 }
 }
 }
}

@Composable
fun SearchHistorySection(
 searchHistory: List<com.example.kiendatn2.data.SearchHistory>,
 onHistoryItemClick: (String) -> Unit,
 onDeleteHistoryItem: (String) -> Unit,
 onClearHistory: () -> Unit
) {
 if (searchHistory.isEmpty()) return

 Divider(modifier = Modifier.padding(vertical = 8.dp))

 Row(
 modifier = Modifier
 .fillMaxWidth()
 .padding(horizontal = 16.dp, vertical = 8.dp),
 horizontalArrangement = Arrangement.SpaceBetween,
 verticalAlignment = Alignment.CenterVertically
 ) {
 Text(
 text = stringResource(R.string.recent_searches),
 style = MaterialTheme.typography.titleMedium
 )

 IconButton(onClick = onClearHistory) {
 Icon(
 imageVector = Icons.Filled.Delete,
 contentDescription = stringResource(R.string.clear_search_history)
 )
 }
 }

 LazyColumn(modifier = Modifier.heightIn(max = 200.dp)) {
 items(searchHistory) { historyItem ->
 SearchHistoryItem(
 historyItem = historyItem,
 onItemClick = { onHistoryItemClick(historyItem.query) },
 onDeleteClick = { onDeleteHistoryItem(historyItem.id) }
 )
 }
 }
}

@Composable
fun SearchHistoryItem(
 historyItem: com.example.kiendatn2.data.SearchHistory,
 onItemClick: () -> Unit,
 onDeleteClick: () -> Unit
) {
 Surface(
 onClick = onItemClick,
 modifier = Modifier.fillMaxWidth()
 ) {
 Row(
 modifier = Modifier
 .fillMaxWidth()
 .padding(horizontal = 16.dp, vertical = 12.dp),
 verticalAlignment = Alignment.CenterVertically,
 horizontalArrangement = Arrangement.SpaceBetween
 ) {
 // Search icon and query text
 Row(
 verticalAlignment = Alignment.CenterVertically
 ) {
 Icon(
 imageVector = Icons.Filled.Search,
 contentDescription = stringResource(R.string.recent_searches),
 modifier = Modifier.padding(end = 8.dp)
 )
 Text(text = historyItem.query)
 }

 // Delete button
 IconButton(onClick = onDeleteClick) {
 Icon(
 imageVector = Icons.Filled.Clear,
 contentDescription = stringResource(R.string.remove_from_history)
 )
 }
 }
 Divider(modifier = Modifier.fillMaxWidth())
 }
}
