 one\n for (const collection of collections) {\n await deleteCollection(collection);\n }\n \n console.log('All Firebase data deleted successfully!');\n } catch (error) {\n console.error('Error deleting data:', error);\n } finally {\n process.exit();\n }\n}\n\ndeleteAllData();"}"}}]},{"role":"tool","name":"edit_file","tool_call_id":"toolu_bdrk_017vTu5Y5fpigCsZMj7cWvv1","content":"The apply model made the following changes to the file:

