+
+async function deleteCollection(collectionName) {
+ console.log(`Deleting collection: ${collectionName}`);
+ 
+ const collectionRef = db.collection(collectionName);
+ const snapshot = await collectionRef.get();
+ 
+ if (snapshot.empty) {
+ console.log(`Collection ${collectionName} is already empty.`);
+ return;
+ }
+ 
+ // Create a batch to delete documents in chunks
+ let batch = db.batch();
+ let count = 0;
+ 
+ for (const doc of snapshot.docs) {
+ batch.delete(doc.ref);
+ count++;
+ 
+ // Firestore batches are limited to 500 operations
+ if (count >= 450) {
+ console.log(`Committing batch of ${count} deletes for ${collectionName}...`);
+ await batch.commit();
+ batch = db.batch();
+ count = 0;
+ }
+ }
+ 
+ // Commit any remaining deletes
+ if (count > 0) {
+ console.log(`Committing final batch of ${count} deletes for ${collectionName}...`);
+ await batch.commit();
+ }
+ 
+ console.log(`Finished deleting collection: ${collectionName}`);
+}
+
+async function deleteAllData() {
+ try {
+ console.log('Starting deletion of all Firebase data...');
+ 
+ // Delete each collection one by one
+ for (const collection of collections) {
+ await deleteCollection(collection);
+ }
+ 
+ console.log('All Firebase data deleted successfully!');
+ } catch (error) {
+ console.error('Error deleting data:', error);
+ } finally {
+ process.exit();
+ }
+}
+
+deleteAllData();
