@Composable
fun MediaPicker(
 onImageSelected: (Uri) -> Unit,
 onDismiss: () -> Unit,
 hasPermission: Boolean,
 requestPermission: () -> Unit
) {
 val context = LocalContext.current
 val state by rememberMediaImages(hasPermission)

 Column(
 modifier = Modifier
 .fillMaxWidth()
 .background(LocalCustomColors.current.navBarsBackground)
 .padding(16.dp)
 ) {
 Text(
 text = stringResource(R.string.select_image),
 style = MaterialTheme.typography.headlineSmall,
 color = LocalCustomColors.current.textPrimary,
 modifier = Modifier.padding(bottom = 16.dp)
 )

 when (state) {
 is MediaQueryState.Loading -> {
 Box(
 modifier = Modifier
 .fillMaxWidth()
 .height(200.dp),
 contentAlignment = Alignment.Center
 ) {
 CircularProgressIndicator()
 }
 }
 is MediaQueryState.Success -> {
 val images = (state as MediaQueryState.Success).images
 if (images.isEmpty()) {
 Box(
 modifier = Modifier
 .fillMaxWidth()
 .height(200.dp),
 contentAlignment = Alignment.Center
 ) {
 Text(
 text = stringResource(R.string.no_images_found),
 color = LocalCustomColors.current.textPrimary
 )
 }
 } else {
 LazyVerticalGrid(
 columns = GridCells.Fixed(3),
 verticalArrangement = Arrangement.spacedBy(8.dp),
 horizontalArrangement = Arrangement.spacedBy(8.dp),
 modifier = Modifier.height(400.dp)
 ) {
 items(images) { image ->
 Box(
 modifier = Modifier
 .size(100.dp)
 .clip(RoundedCornerShape(8.dp))
 .border(1.dp, Color.Gray, RoundedCornerShape(8.dp))
 .shadow(4.dp, RoundedCornerShape(8.dp))
 .clickable {
 onImageSelected(image.uri)
 onDismiss()
 }
 ) {
 AsyncImage(
 model = image.uri,
 contentDescription = "Image thumbnail: ${image.displayName}",
 contentScale = ContentScale.Crop,
 modifier = Modifier.fillMaxSize()
 )
 }
 }
 }
 }
 }
 is MediaQueryState.Error -> {
 Box(
 modifier = Modifier
 .fillMaxWidth()
 .height(200.dp),
 contentAlignment = Alignment.Center
 ) {
 Column(horizontalAlignment = Alignment.CenterHorizontally) {
 Text(
 text = "Permission required to access images",
 color = LocalCustomColors.current.textPrimary
 )
 Spacer(modifier = Modifier.height(8.dp))
 Button(onClick = { requestPermission() }) {
 Text("Grant Permission")
 }
 }
 }
 }
 }

 Spacer(modifier = Modifier.height(16.dp))

 TextButton(
 onClick = { onDismiss() },
 modifier = Modifier.align(Alignment.End)
 ) {
 Text(
 text = stringResource(R.string.cancel),
 color = LocalCustomColors.current.textPrimary
 )
 }
 }
}

@Composable
fun rememberMediaImages(hasPermission: Boolean): androidx.compose.runtime.State<MediaQueryState> {
 val context = LocalContext.current
 val state = remember { mutableStateOf<MediaQueryState>(MediaQueryState.Loading) }

 LaunchedEffect(hasPermission) {
 if (!hasPermission) {
 state.value = MediaQueryState.Error
 return@LaunchedEffect
 }

 val imageList = mutableListOf<MediaImage>()
 val projection = arrayOf(
 MediaStore.Images.Media._ID,
 MediaStore.Images.Media.DISPLAY_NAME
 )
 val selection = "${MediaStore.Images.Media.MIME_TYPE} IN (?, ?)"
 val selectionArgs = arrayOf("image/jpeg", "image/png")
 val sortOrder = "${MediaStore.Images.Media.DATE_MODIFIED} DESC"

 context.contentResolver.query(
 MediaStore.Images.Media.EXTERNAL_CONTENT_URI,
 projection,
 selection,
 selectionArgs,
 sortOrder
 )?.use { cursor ->
 val idColumn = cursor.getColumnIndexOrThrow(MediaStore.Images.Media._ID)
 val nameColumn = cursor.getColumnIndexOrThrow(MediaStore.Images.Media.DISPLAY_NAME)
 while (cursor.moveToNext()) {
 val id = cursor.getLong(idColumn)
 val name = cursor.getString(nameColumn) ?: "Unknown"
 val uri = Uri.withAppendedPath(
 MediaStore.Images.Media.EXTERNAL_CONTENT_URI,
 id.toString()
 )
 imageList.add(MediaImage(uri, name))
 }
 }

 // Query internal storage
 context.contentResolver.query(
 MediaStore.Images.Media.INTERNAL_CONTENT_URI,
 projection,
 selection,
 selectionArgs,
 sortOrder
 )?.use { cursor ->
 val idColumn = cursor.getColumnIndexOrThrow(MediaStore.Images.Media._ID)
 val nameColumn = cursor.getColumnIndexOrThrow(MediaStore.Images.Media.DISPLAY_NAME)
 while (cursor.moveToNext()) {
 val id = cursor.getLong(idColumn)
 val name = cursor.getString(nameColumn) ?: "Unknown"
 val uri = Uri.withAppendedPath(
 MediaStore.Images.Media.INTERNAL_CONTENT_URI,
 id.toString()
 )
 imageList.add(MediaImage(uri, name))
 }
 }

 state.value = MediaQueryState.Success(imageList)
 }

 return state
}

sealed class MediaQueryState {
 object Loading : MediaQueryState()
 data class Success(val images: List<MediaImage>) : MediaQueryState()
 object Error : MediaQueryState()
}
