nt = Alignment.Center\n ) {\n Text(\n text = stringResource(if (includeVideos) R.string.no_media_found else R.string.no_images_found),\n color = LocalCustomColors.current.textPrimary\n )\n }\n } else {\n LazyVerticalGrid(\n columns = GridCells.Fixed(3),\n verticalArrangement = Arrangement.spacedBy(8.dp),\n horizontalArrangement = Arrangement.spacedBy(8.dp),\n modifier = Modifier.height(400.dp)\n ) {\n items(mediaItems) { mediaItem ->\n Box(\n modifier = Modifier\n .size(100.dp)\n .clip(RoundedCornerShape(8.dp))\n .border(1.dp, Color.Gray, RoundedCornerShape(8.dp))\n .shadow(4.dp, RoundedCornerShape(8.dp))\n .clickable {\n onMediaSelected(mediaItem.uri, mediaItem.isVideo)\n onDismiss()\n }\n ) {\n AsyncImage(\n model = mediaItem.uri,\n contentDescription = \"Media thumbnail: ${mediaItem.displayName}\",\n contentScale = ContentScale.Crop,\n modifier = Modifier.fillMaxSize()\n )\n \n // Show play icon overlay for videos\n if (mediaItem.isVideo) {\n Box(\n modifier = Modifier\n .fillMaxSize()\n .background(Color.Black.copy(alpha = 0.3f)),\n contentAlignment = Alignment.Center\n ) {\n Icon(\n imageVector = Icons.Default.PlayArrow,\n contentDescription = \"Video\",\n tint = Color.White,\n modifier = Modifier.size(32.dp)\n )\n }\n }\n }\n }\n }\n }\n }\n is MediaQueryState.Error -> {\n Box(\n modifier = Modifier\n .fillMaxWidth()\n .height(200.dp),\n contentAlignment = Alignment.Center\n ) {\n Column(horizontalAlignment = Alignment.CenterHorizontally) {\n Text(\n text = \"Permission required to access media\",\n color = LocalCustomColors.current.textPrimary\n )\n Spacer(modifier = Modifier.height(8.dp))\n Button(onClick = { requestPermission() }) {\n Text(\"Grant Permission\")\n }\n }\n }\n }\n }\n\n Spacer(modifier = Modifier.height(16.dp))\n\n TextButton(\n onClick = { onDismiss() },\n modifier = Modifier.align(Alignment.End)\n ) {\n Text(\n text = stringResource(R.string.cancel),\n color = LocalCustomColors.current.textPrimary\n )\n }\n }\n}\n\n@Composable\nfun remember