@Composable
fun PostItem(
 authorName: String,
 content: String,
 imageUrl: String? = null,
 videoUrl: String? = null,
 hasVideo: Boolean = false,
 likeCount: Int = 0,
 isLikedByCurrentUser: Boolean = false,
 commentCount: Int = 0,
 shareCount: Int = 0,
 profilePictureUrl: String? = null,
 onLikeClick: () -> Unit = {},
 onCommentClick: () -> Unit = {},
 onShareClick: () -> Unit = {},
 userId: String? = null,
