 suspend fun createPostWithMediaUrl(
 text: String,
 mediaUrl: String?,
 isVideo: Boolean = false,
 visibility: PostVisibility = PostVisibility.PUBLIC
 ): Post =
 withContext(Dispatchers.IO) {
