 .orderBy("createdAt", Query.Direction.DESCENDING)
 .get()
 .await()
 .toObjects(Post::class.java)
 }

 // Add function to check if posts are liked by current user
 suspend fun getPostsWithLikeStatus(): List<Post> = withContext(Dispatchers.IO) {
 val currentUser = auth.currentUser ?: return@withContext emptyList<Post>()

 try {
 // Get all posts
 val posts = postsCollection
 .get()
 .await()
 .toObjects(Post::class.java)
 .sortedByDescending { it.createdAt }

 // Get all likes by current user
 val userLikes = likesCollection
 .whereEqualTo("userId", currentUser.uid)
 .get()
 .await()
 .documents
 .map { it.getString("postId") ?: "" }
 .toSet()

 // Get user's friends to filter private posts
 val friendships = friendshipsCollection
 .whereEqualTo("userId", currentUser.uid)
 .whereEqualTo("status", "ACCEPTED")
 .get()
 .await()
 .documents
 .mapNotNull { it.getString("friendId") }
 .toSet()

 // Debug post image URLs
 posts.forEach { post ->
 if (post.imageUrl != null) {
 android.util.Log.d(
 "FirebaseRepository",
 "Post ID: ${post.id}, Image URL: ${post.imageUrl}"
 )
 try {
 // Try to validate the image URL by checking if the file exists
 val storageRef = storage.getReferenceFromUrl(post.imageUrl!!)
 android.util.Log.d("FirebaseRepository", "Storage path: ${storageRef.path}")
 } catch (e: Exception) {
 android.util.Log.e(
 "FirebaseRepository",
 "Invalid image URL: ${post.imageUrl}",
 e
 )
 }
 }
 }

 // Filter posts based on privacy settings:
 // 1. Show public posts from everyone
 // 2. Show private posts only from friends and self
 val filteredPosts = posts.filter { post ->
 !post.isPrivate || // Public posts are visible to everyone
 post.userId == currentUser.uid || // User's own posts are always visible
 friendships.contains(post.userId) // Friend's private posts are visible
 }

 // Mark posts as liked if they are in the userLikes set
 return@withContext filteredPosts.map { post ->
 post.copy(isLikedByCurrentUser = userLikes.contains(post.id))
 }
 } catch (e: Exception) {
 // Fallback in case of errors
 return@withContext emptyList()
 }
 }

 // Add function to get posts from friends
 suspend fun getFriendsPostsWithLikeStatus(): List<Post> = withContext(Dispatchers.IO) {
 val currentUser = auth.currentUser ?: return@withContext emptyList<Post>()

 try {
 // First get all friendship connections - Get friendships both as sender and receiver
 val senderFriendships = friendshipsCollection
 .whereEqualTo("senderId", currentUser.uid)
 .whereEqualTo("status", FriendshipStatus.ACCEPTED.name)
 .get()
 .await()
 .documents
 .mapNotNull { it.getString("receiverId") }
 .toSet()

 val receiverFriendships = friendshipsCollection
 .whereEqualTo("receiverId", currentUser.uid)
 .whereEqualTo("status", FriendshipStatus.ACCEPTED.name)
 .get()
 .await()
 .documents
 .mapNotNull { it.getString("senderId") }
 .toSet()

 // Combine both friendship lists
 val friendships = senderFriendships + receiverFriendships

 if (friendships.isEmpty()) {
 android.util.Log.d(
 "FirebaseRepository",
 "User has no friends, returning empty list"
 )
 return@withContext emptyList()
 }

 android.util.Log.d("FirebaseRepository", "Found ${friendships.size} friends")

 // Debug - Log friend IDs
 friendships.forEach { friendId ->
 android.util.Log.d("FirebaseRepository", "Friend ID: $friendId")
 }

 // Get all posts
 val allPosts = postsCollection
 .get()
 .await()
 .toObjects(Post::class.java)

 android.util.Log.d("FirebaseRepository", "Found ${allPosts.size} total posts")

 // Filter posts to only include those from friends, respecting privacy settings
 val friendPosts = allPosts.filter { post ->
 friendships.contains(post.userId) && // Post is from a friend
 (!post.isPrivate || // Either it's public
 friendships.contains(post.userId)) // Or it's private but from a friend
 }.sortedByDescending { it.createdAt }

 android.util.Log.d("FirebaseRepository", "Filtered to ${friendPosts.size} friend posts")

 // Get all likes by current user
 val userLikes = likesCollection
 .whereEqualTo("userId", currentUser.uid)
 .get()
 .await()
 .documents
 .mapNotNull { it.getString("postId") }
 .toSet()

 // Mark posts as liked if they are in the userLikes set
 return@withContext friendPosts.map { post ->
 post.copy(isLikedByCurrentUser = userLikes.contains(post.id))
 }
 } catch (e: Exception) {
 android.util.Log.e("FirebaseRepository", "Error getting friends' posts", e)
 return@withContext emptyList()
 }
 }

 // Search for posts by content
 suspend fun searchPosts(query: String): List<Post> = withContext(Dispatchers.IO) {
 if (query.length < 2) return@withContext emptyList()

 val currentUser = auth.currentUser ?: return@withContext emptyList()

 try {
 // Get all posts
 val allPosts = postsCollection
 .get()
 .await()
 .toObjects(Post::class.java)
 .sortedByDescending { it.createdAt }

 // Get all likes by current user
 val userLikes = likesCollection
 .whereEqualTo("userId", currentUser.uid)
 .get()
 .await()
 .documents
 .mapNotNull { it.getString("postId") }
 .toSet()

 // Get user's friends to filter private posts
 val friendships = friendshipsCollection
 .whereEqualTo("userId", currentUser.uid)
 .whereEqualTo("status", "ACCEPTED")
 .get()
 .await()
 .documents
 .mapNotNull { it.getString("friendId") }
 .toSet()

 // Filter posts based on:
 // 1. Post text contains query (case insensitive)
 // 2. Privacy settings (same as in getPostsWithLikeStatus)
 val filteredPosts = allPosts.filter { post ->
 post.text.contains(query, ignoreCase = true) &&
 (!post.isPrivate || post.userId == currentUser.uid || friendships.contains(
 post.userId
 ))
 }

 // Mark posts as liked if they are in the userLikes set
 return@withContext filteredPosts.map { post ->
 post.copy(isLikedByCurrentUser = userLikes.contains(post.id))
 }
 } catch (e: Exception) {
 Log.e("FirebaseRepository", "Error searching posts: ${e.message}", e)
 return@withContext emptyList()
 }
 }

 // Comment operations
 suspend fun addComment(postId: String, text: String, imageUri: Uri?): Comment = withContext(Dispatchers.IO) {
 val currentUser = auth.currentUser ?: throw IllegalStateException("No user logged in")

 // Get the user display name
 val userDisplayName = currentUser.displayName ?: "Unknown User"

 // If image is included, try to upload to storage first
 var imageUrl: String? = null
 if (imageUri != null) {
 try {
 imageUrl = uploadImage(imageUri, "comments")
 } catch (e: Exception) {
 // Log the error but continue creating comment without image
 android.util.Log.e(
 "FirebaseRepository",
 "Failed to upload comment image: ${e.message}"
 )
 // If image upload fails, we'll proceed with creating the comment without an image
 }
 }

 val commentId = commentsCollection.document().id
 val comment = Comment(
 id = commentId,
 postId = postId,
 userId = currentUser.uid,
 userDisplayName = userDisplayName, 
 text = text,
 imageUrl = imageUrl,
 createdAt = Timestamp.now()
 )

 commentsCollection.document(commentId).set(comment).await()

 // Increment comment count
 postsCollection.document(postId).update("commentCount",
 FieldValue.increment(1)).await()

 // Create notification for the comment
 val post = getPostById(postId) ?: return@withContext comment
 val user = getCurrentUser() ?: return@withContext comment
 if (post.userId != user.id) {
 notificationRepository.createCommentNotification(post, commentId, user)
 } else {
 Log.d("FirebaseRepository", "Skipping self-notification for comment")
 }

 comment
 }

