 // Add method to check for self-notifications
 suspend fun checkSelfNotifications() = withContext(Dispatchers.IO) {
 try {
 val currentUser = getCurrentUser() ?: return@withContext

 // Check for self-notifications
 val notifications = firestore.collection("notifications")
 .whereEqualTo("recipientId", currentUser.id)
 .whereEqualTo("senderId", currentUser.id)
 .get()
 .await()

 if (!notifications.isEmpty) {
 android.util.Log.e("FirebaseRepository", 
 "Found ${notifications.size()} self-notifications for user ${currentUser.id}")

 // Optional: clean up existing self-notifications
 val batch = firestore.batch()
 for (doc in notifications.documents) {
 batch.delete(doc.reference)
 }
 batch.commit()
 } else {
 android.util.Log.d("FirebaseRepository", "No self-notifications found")
 }
 } catch (e: Exception) {
 android.util.Log.e("FirebaseRepository", "Error checking self-notifications: ${e.message}")
 }
 }

