 }
 batch.commit().await()

 Log.d(
 "FirebaseRepository",
 "Successfully unhid post: $postId for user: ${currentUser.uid}"
 )
 return@withContext true

 } catch (e: Exception) {
 Log.e("FirebaseRepository", "Error unhiding post: ${e.message}", e)
 return@withContext false
 }
 }

