 "Successfully unarchived post: $postId for user: ${currentUser.uid}"
 )
 return@withContext true

 } catch (e: Exception) {
 Log.e("FirebaseRepository", "Error unarchiving post: ${e.message}", e)
 return@withContext false
 }
 }

