package com.example.kiendatn2.repository

import android.net.Uri
import android.util.Log
import com.example.kiendatn2.data.Comment
import com.example.kiendatn2.data.FriendshipStatus
import com.example.kiendatn2.data.Notification
import com.example.kiendatn2.data.Post
import com.example.kiendatn2.data.SearchHistory
import com.example.kiendatn2.data.SharedPost
import com.example.kiendatn2.data.User
import com.google.firebase.Timestamp
import com.google.firebase.auth.FirebaseAuth
import com.google.firebase.firestore.FieldValue
import com.google.firebase.firestore.FirebaseFirestore
import com.google.firebase.firestore.Query
import com.google.firebase.storage.FirebaseStorage
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.tasks.await
import kotlinx.coroutines.withContext

class FirebaseRepository {
 private val auth = FirebaseAuth.getInstance()
 private val firestore = FirebaseFirestore.getInstance()
 private val storage = FirebaseStorage.getInstance()

 private val usersCollection = firestore.collection("users")
 private val postsCollection = firestore.collection("posts")
 private val commentsCollection = firestore.collection("comments")
 private val likesCollection = firestore.collection("likes")
 private val commentLikesCollection = firestore.collection("commentLikes")
 private val friendshipsCollection = firestore.collection("friendships")
 private val notificationRepository = NotificationRepository()
 private val searchHistoryCollection = firestore.collection("searchHistory")
 private val sharedPostsCollection = firestore.collection("sharedPosts")

 // Current user operations
 fun getCurrentFirebaseUser() = auth.currentUser

 suspend fun createUserProfile(user: User) = withContext(Dispatchers.IO) {
 val currentUser = auth.currentUser ?: throw IllegalStateException("No user logged in")
 val userData = user.copy(id = currentUser.uid, email = currentUser.email ?: "")
 usersCollection.document(currentUser.uid).set(userData).await()
 }

 suspend fun getCurrentUser(): User? = withContext(Dispatchers.IO) {
 try {
 val currentUser = auth.currentUser ?: return@withContext null
 val userDoc = usersCollection.document(currentUser.uid).get().await()

 // Debug log to check what we're getting from Firestore
 if (!userDoc.exists()) {
 Log.e(
 "FirebaseRepository",
 "User document doesn't exist for UID: ${currentUser.uid}"
 )
 return@withContext null
 } else {
 Log.d("FirebaseRepository", "Retrieved user doc data: ${userDoc.data}")
 }

 val user = userDoc.toObject(User::class.java)

 // If we got a user but it doesn't have an ID field populated, update it
 if (user != null && user.id.isBlank()) {
 Log.d(
 "FirebaseRepository",
 "User exists but has blank ID, using UID: ${currentUser.uid}"
 )
 return@withContext user.copy(id = currentUser.uid)
 }

 return@withContext user
 } catch (e: Exception) {
 Log.e("FirebaseRepository", "Error getting current user", e)
 throw e
 }
 }

 // Password change operation
 suspend fun changePassword(currentPassword: String, newPassword: String): Result<Unit> =
 withContext(Dispatchers.IO) {
 try {
 val currentUser = auth.currentUser ?: return@withContext Result.failure(
 IllegalStateException("No user logged in")
 )
 val email = currentUser.email ?: return@withContext Result.failure(
 IllegalStateException("User has no email")
 )

 // Re-authenticate user first
 val credential =
 com.google.firebase.auth.EmailAuthProvider.getCredential(email, currentPassword)
 currentUser.reauthenticate(credential).await()

 // Then update password
 currentUser.updatePassword(newPassword).await()
 return@withContext Result.success(Unit)
 } catch (e: Exception) {
 Log.e("FirebaseRepository", "Error changing password", e)
 return@withContext Result.failure(e)
 }
 }

 // User profile operations
 suspend fun updateUserProfile(displayName: String, bio: String?, photoUri: Uri?): User = withContext(Dispatchers.IO) {
 val currentUser = auth.currentUser ?: throw IllegalStateException("No user logged in")

 // Upload photo if provided - handle potential failures
 var photoUrl = getCurrentUser()?.photoUrl
 if (photoUri != null) {
 try {
 photoUrl = uploadImage(photoUri, "profiles")
 } catch (e: Exception) {
 // Log error but continue with profile update without changing photo
 Log.e(
 "FirebaseRepository",
 "Failed to upload profile photo: ${e.message}"
 )
 }
 }

 // Create updated user data
 val userData = mapOf(
 "displayName" to displayName,
 "bio" to bio,
 "photoUrl" to photoUrl
 )

 // Update user document
 usersCollection.document(currentUser.uid).update(userData).await()

 // Update profile picture and display name in all user's posts
 updateUserPostsProfilePicture(photoUrl, displayName)

 // Update display name in all user's comments
 updateUserCommentsDisplayName(displayName)

 // Return updated user
 getCurrentUser() ?: throw IllegalStateException("Failed to get updated user")
 }

 suspend fun updateUserProfileWithCloudinaryUrl(
 displayName: String,
 bio: String?,
 cloudinaryUrl: String?
 ): User = withContext(Dispatchers.IO) {
 val currentUser = auth.currentUser ?: throw IllegalStateException("No user logged in")

 // Create updated user data
 val userData = mapOf(
 "displayName" to displayName,
 "bio" to bio,
 "photoUrl" to cloudinaryUrl
 )

 // Update user document
 usersCollection.document(currentUser.uid).update(userData).await()

 // Update profile picture and display name in all user's posts
 updateUserPostsProfilePicture(cloudinaryUrl, displayName)

 // Update display name in all user's comments
 updateUserCommentsDisplayName(displayName)

 // Return updated user
 getCurrentUser() ?: throw IllegalStateException("Failed to get updated user")
 }

 /**
 * Update the profile picture URL and display name in all posts by the current user
 */
 private suspend fun updateUserPostsProfilePicture(
 profilePictureUrl: String?,
 displayName: String? = null
 ) =
 withContext(Dispatchers.IO) {
 try {
 val currentUser = auth.currentUser ?: return@withContext

 // Get all posts by this user
 val userPosts = postsCollection
 .whereEqualTo("userId", currentUser.uid)
 .get()
 .await()

 if (!userPosts.isEmpty) {
 val batch = firestore.batch()

 // Update each post with the new profile picture URL and/or display name
 for (postDoc in userPosts.documents) {
 // Check what fields need to be updated
 if (profilePictureUrl != null && displayName != null) {
 // Update both profile picture and display name
 batch.update(
 postDoc.reference,
 mapOf(
 "userProfilePicture" to profilePictureUrl,
 "userDisplayName" to displayName
 )
 )
 } else if (profilePictureUrl != null) {
 // Update only profile picture
 batch.update(
 postDoc.reference,
 "userProfilePicture",
 profilePictureUrl
 )
 } else if (displayName != null) {
 // Update only display name
 batch.update(
 postDoc.reference,
 "userDisplayName",
 displayName
 )
 }
 }

 // Commit all updates in a single batch
 batch.commit().await()

 // Create a detailed log message
 val updatedFields = mutableListOf<String>()
 if (profilePictureUrl != null) updatedFields.add("profile picture")
 if (displayName != null) updatedFields.add("display name")

 android.util.Log.d(
 "FirebaseRepository",
 "Updated ${updatedFields.joinToString(" and ")} in ${userPosts.size()} posts"
 )
 }
 } catch (e: Exception) {
 // Create a detailed error message
 val updatedFields = mutableListOf<String>()
 if (profilePictureUrl != null) updatedFields.add("profile picture")
 if (displayName != null) updatedFields.add("display name")
 android.util.Log.e(
 "FirebaseRepository",
 "Error updating ${updatedFields.joinToString(" and ")} in posts: ${e.message}",
 e
 )
 }
 }

 /**
 * Update the display name in all comments and replies by the current user
 */
 private suspend fun updateUserCommentsDisplayName(displayName: String) =
 withContext(Dispatchers.IO) {
 try {
 val currentUser = auth.currentUser ?: return@withContext

 // Get all comments by this user
 val userComments = commentsCollection
 .whereEqualTo("userId", currentUser.uid)
 .get()
 .await()

 // Count total updated documents
 var totalUpdated = 0

 if (!userComments.isEmpty) {
 val batch = firestore.batch()

 // Update each comment with the new display name
 for (commentDoc in userComments.documents) {
 batch.update(
 commentDoc.reference,
 "userDisplayName",
 displayName
 )
 }

 // Commit all updates in a single batch
 batch.commit().await()
 totalUpdated += userComments.size()

 }

 // Get all replies by this user (also stored in comments collection, but with parentCommentId field)
 val userReplies = commentsCollection
 .whereEqualTo("userId", currentUser.uid)
 .whereGreaterThan("parentCommentId", "") // Filter for replies
 .get()
 .await()

 if (!userReplies.isEmpty) {
 val batch = firestore.batch()

 // Update each reply with the new display name
 for (replyDoc in userReplies.documents) {
 batch.update(
 replyDoc.reference,
 "userDisplayName",
 displayName
 )
 }

 // Commit all updates in a single batch
 batch.commit().await()
 totalUpdated += userReplies.size()
 }

 // Log total updates
 android.util.Log.d(
 "FirebaseRepository",
 "Updated display name in $totalUpdated comments and replies"
 )
 } catch (e: Exception) {
 android.util.Log.e(
 "FirebaseRepository",
 "Error updating display name in comments and replies: ${e.message}",
 e
 )
 }
 }

 // Get user by ID
 suspend fun getUserById(userId: String): User? = withContext(Dispatchers.IO) {
 try {
 val userDoc = usersCollection.document(userId).get().await()

 if (!userDoc.exists()) {
 Log.e("FirebaseRepository", "User document doesn't exist for UID: $userId")
 return@withContext null
 }

 return@withContext userDoc.toObject(User::class.java)
 } catch (e: Exception) {
 Log.e("FirebaseRepository", "Error getting user by ID", e)
 throw e
 }
 }

 // Get posts by specific user ID
 suspend fun getUserPostsById(userId: String): List<Post> = withContext(Dispatchers.IO) {
 val currentUser = auth.currentUser

 try {
 Log.d("FirebaseRepository", "Getting posts for user ID: $userId")
 // Get posts by the specified user ID
 val postsQuery = postsCollection
 .whereEqualTo("userId", userId)
 .orderBy("createdAt", Query.Direction.DESCENDING)

 val snapshot = postsQuery.get().await()
 Log.d("FirebaseRepository", "Found ${snapshot.size()} posts")

 val posts = snapshot.toObjects(Post::class.java)

 // If current user is logged in, check which posts they've liked
 if (currentUser != null) {
 val userLikes = likesCollection
 .whereEqualTo("userId", currentUser.uid)
 .get()
 .await()
 .documents
 .map { it.getString("postId") ?: "" }
 .toSet()

 // Mark posts as liked if they are in the userLikes set
 return@withContext posts.map { post ->
 post.copy(isLikedByCurrentUser = userLikes.contains(post.id))
 }
 } else {
 return@withContext posts
 }
 } catch (e: Exception) {
 // Fallback to a simpler query if index not available
 val posts = postsCollection
 .get()
 .await()
 .toObjects(Post::class.java)
 .filter { it.userId == userId }
 .sortedByDescending { it.createdAt }

 return@withContext posts
 }
 }

 // Get posts by current user
 suspend fun getUserPosts(): List<Post> = withContext(Dispatchers.IO) {
 val currentUser = auth.currentUser ?: throw IllegalStateException("No user logged in")

 try {
 android.util.Log.d("FirebaseRepository", "Getting posts for user: ${currentUser.uid}")
 // Get posts by the current user
 val postsQuery = postsCollection
 .whereEqualTo("userId", currentUser.uid)
 .orderBy("createdAt", Query.Direction.DESCENDING)

 // Debug the query
 android.util.Log.d(
 "FirebaseRepository",
 "Query: posts collection with userId=${currentUser.uid}"
 )

 val snapshot = postsQuery.get().await()
 android.util.Log.d("FirebaseRepository", "Found ${snapshot.size()} posts")

 val posts = snapshot.toObjects(Post::class.java)

 // Get likes by current user to mark which posts are liked
 val userLikes = likesCollection
 .whereEqualTo("userId", currentUser.uid)
 .get()
 .await()
 .documents
 .map { it.getString("postId") ?: "" }
 .toSet()

 // Mark posts as liked if they are in the userLikes set
 return@withContext posts.map { post ->
 post.copy(isLikedByCurrentUser = userLikes.contains(post.id))
 }
 } catch (e: Exception) {
 // Fallback to a simpler query if index not available
 val posts = postsCollection
 .get()
 .await()
 .toObjects(Post::class.java)
 .filter { it.userId == currentUser.uid }
 .sortedByDescending { it.createdAt }

 return@withContext posts
 }
 }

 // Post operations
 suspend fun createPost(text: String, imageUri: Uri?): Post = withContext(Dispatchers.IO) {
 val currentUser = auth.currentUser ?: throw IllegalStateException("No user logged in")

 // Get the user data
 val userDisplayName = currentUser.displayName ?: "Unknown User"
 val userProfile = getCurrentUser()
 val userProfilePicture = userProfile?.photoUrl

 // If image is included, try to upload to storage first
 var imageUrl: String? = null
 if (imageUri != null) {
 try {
 imageUrl = uploadImage(imageUri, "posts")
 } catch (e: Exception) {
 // Log the error but continue creating post without image
 android.util.Log.e("FirebaseRepository", "Failed to upload image: ${e.message}")
 // If image upload fails, we'll proceed with creating the post without an image
 }
 }

 val postId = postsCollection.document().id
 val post = Post(
 id = postId,
 userId = currentUser.uid,
 userDisplayName = userDisplayName,
 userProfilePicture = userProfilePicture,
 text = text,
 imageUrl = imageUrl,
 createdAt = Timestamp.now()
 )

 postsCollection.document(postId).set(post).await()
 post
 }

 /**
 * Create a post with a provided Cloudinary image URL
 */
 suspend fun createPostWithImageUrl(text: String, imageUrl: String?): Post =
 withContext(Dispatchers.IO) {
 val currentUser = auth.currentUser ?: throw IllegalStateException("No user logged in")

 // Get the user data
 val userDisplayName = currentUser.displayName ?: "Unknown User"
 val userProfile = getCurrentUser()
 val userProfilePicture = userProfile?.photoUrl

 val postId = postsCollection.document().id
 val post = Post(
 id = postId,
 userId = currentUser.uid,
 userDisplayName = userDisplayName,
 userProfilePicture = userProfilePicture,
 text = text,
 imageUrl = imageUrl,
 createdAt = Timestamp.now()
 )

 postsCollection.document(postId).set(post).await()
 post
 }

 /**
 * Create a post with a provided Cloudinary media URL (image or video)
 */
 suspend fun createPostWithMediaUrl(
 text: String,
 mediaUrl: String?,
 isVideo: Boolean = false
 ): Post =
 withContext(Dispatchers.IO) {
 val currentUser = auth.currentUser ?: throw IllegalStateException("No user logged in")

 // Get the user data
 val userDisplayName = currentUser.displayName ?: "Unknown User"
 val userProfile = getCurrentUser()
 val userProfilePicture = userProfile?.photoUrl

 val postId = postsCollection.document().id
 val post = if (isVideo) {
 Post(
 id = postId,
 userId = currentUser.uid,
 userDisplayName = userDisplayName,
 userProfilePicture = userProfilePicture,
 text = text,
 videoUrl = mediaUrl,
 hasVideo = true,
 createdAt = Timestamp.now()
 )
 } else {
 Post(
 id = postId,
 userId = currentUser.uid,
 userDisplayName = userDisplayName,
 userProfilePicture = userProfilePicture,
 text = text,
 imageUrl = mediaUrl,
 createdAt = Timestamp.now()
 )
 }

 postsCollection.document(postId).set(post).await()
 post
 }

 suspend fun getPosts(): List<Post> = withContext(Dispatchers.IO) {
 postsCollection
 .orderBy("createdAt", Query.Direction.DESCENDING)
 .get()
 .await()
 .toObjects(Post::class.java)
 }

 // Add function to check if posts are liked by current user
 suspend fun getPostsWithLikeStatus(): List<Post> = withContext(Dispatchers.IO) {
 val currentUser = auth.currentUser ?: return@withContext emptyList<Post>()

 try {
 // Get all posts
 val posts = postsCollection
 .get()
 .await()
 .toObjects(Post::class.java)
 .sortedByDescending { it.createdAt }

 // Get all likes by current user
 val userLikes = likesCollection
 .whereEqualTo("userId", currentUser.uid)
 .get()
 .await()
 .documents
 .map { it.getString("postId") ?: "" }
 .toSet()

 // Get user's friends to filter private posts
 val friendships = friendshipsCollection
 .whereEqualTo("userId", currentUser.uid)
 .whereEqualTo("status", "ACCEPTED")
 .get()
 .await()
 .documents
 .mapNotNull { it.getString("friendId") }
 .toSet()

 // Get posts shared by the current user
 val userSharedPosts = sharedPostsCollection
 .whereEqualTo("sharedByUserId", currentUser.uid)
 .get()
 .await()
 .documents
 .mapNotNull { it.getString("originalPostId") }
 .toSet()

 // Debug post image URLs
 posts.forEach { post ->
 if (post.imageUrl != null) {
 android.util.Log.d(
 "FirebaseRepository",
 "Post ID: ${post.id}, Image URL: ${post.imageUrl}"
 )
 try {
 // Try to validate the image URL by checking if the file exists
 val storageRef = storage.getReferenceFromUrl(post.imageUrl!!)
 android.util.Log.d("FirebaseRepository", "Storage path: ${storageRef.path}")
 } catch (e: Exception) {
 android.util.Log.e(
 "FirebaseRepository",
 "Invalid image URL: ${post.imageUrl}",
 e
 )
 }
 }
 }

 // Filter posts based on privacy settings:
 // 1. Show public posts from everyone
 // 2. Show private posts only from friends and self
 val filteredPosts = posts.filter { post ->
 !post.isPrivate || // Public posts are visible to everyone
 post.userId == currentUser.uid || // User's own posts are always visible
 friendships.contains(post.userId) // Friend's private posts are visible
 }

 // Mark posts as liked if they are in the userLikes set
 // and mark posts as shared by current user
 return@withContext filteredPosts.map { post ->
 post.copy(
 isLikedByCurrentUser = userLikes.contains(post.id),
 isSharedByCurrentUser = userSharedPosts.contains(post.id)
 )
 }
 } catch (e: Exception) {
 // Fallback in case of errors
 return@withContext emptyList()
 }
 }

 // Add function to get posts from friends
 suspend fun getFriendsPostsWithLikeStatus(): List<Post> = withContext(Dispatchers.IO) {
 val currentUser = auth.currentUser ?: return@withContext emptyList<Post>()

 try {
 // First get all friendship connections - Get friendships both as sender and receiver
 val senderFriendships = friendshipsCollection
 .whereEqualTo("senderId", currentUser.uid)
 .whereEqualTo("status", FriendshipStatus.ACCEPTED.name)
 .get()
 .await()
 .documents
 .mapNotNull { it.getString("receiverId") }
 .toSet()

 val receiverFriendships = friendshipsCollection
 .whereEqualTo("receiverId", currentUser.uid)
 .whereEqualTo("status", FriendshipStatus.ACCEPTED.name)
 .get()
 .await()
 .documents
 .mapNotNull { it.getString("senderId") }
 .toSet()

 // Combine both friendship lists
 val friendships = senderFriendships + receiverFriendships

 if (friendships.isEmpty()) {
 android.util.Log.d(
 "FirebaseRepository",
 "User has no friends, returning empty list"
 )
 return@withContext emptyList()
 }

 android.util.Log.d("FirebaseRepository", "Found ${friendships.size} friends")

 // Debug - Log friend IDs
 friendships.forEach { friendId ->
 android.util.Log.d("FirebaseRepository", "Friend ID: $friendId")
 }

 // Get all posts
 val allPosts = postsCollection
 .get()
 .await()
 .toObjects(Post::class.java)

 android.util.Log.d("FirebaseRepository", "Found ${allPosts.size} total posts")

 // Filter posts to only include those from friends, respecting privacy settings
 val friendPosts = allPosts.filter { post ->
 friendships.contains(post.userId) && // Post is from a friend
 (!post.isPrivate || // Either it's public
 friendships.contains(post.userId)) // Or it's private but from a friend
 }

 // Get shared posts by friends
 val sharedPosts = getSharedPostsForFriends(friendships)
 android.util.Log.d("FirebaseRepository", "Found ${sharedPosts.size} shared posts")

 // Get posts shared by the current user
 val currentUserSharedPosts = getPostsSharedByCurrentUser()
 android.util.Log.d(
 "FirebaseRepository",
 "Found ${currentUserSharedPosts.size} posts shared by current user"
 )

 // Combine regular posts, friends' shared posts, and current user's shared posts
 val combinedPosts =
 (friendPosts + sharedPosts + currentUserSharedPosts).sortedByDescending { it.createdAt }

 android.util.Log.d(
 "FirebaseRepository",
 "Filtered to ${combinedPosts.size} friend posts"
 )

 // Get all likes by current user
 val userLikes = likesCollection
 .whereEqualTo("userId", currentUser.uid)
 .get()
 .await()
 .documents
 .mapNotNull { it.getString("postId") }
 .toSet()

 // Get posts shared by the current user
 val userSharedPosts = sharedPostsCollection
 .whereEqualTo("sharedByUserId", currentUser.uid)
 .get()
 .await()
 .documents
 .mapNotNull { it.getString("originalPostId") }
 .toSet()

 // Mark posts as liked if they are in the userLikes set
 return@withContext combinedPosts.map { post ->
 post.copy(
 isLikedByCurrentUser = userLikes.contains(post.id),
 isSharedByCurrentUser = userSharedPosts.contains(post.id)
 )
 }
 } catch (e: Exception) {
 android.util.Log.e("FirebaseRepository", "Error getting friends' posts", e)
 return@withContext emptyList()
 }
 }

 /**
 * Get posts shared by the current user
 */
 private suspend fun getPostsSharedByCurrentUser(): List<Post> = withContext(Dispatchers.IO) {
 try {
 val currentUser = auth.currentUser ?: return@withContext emptyList<Post>()

 // Get all posts shared by the current user
 val sharedPostDocs = sharedPostsCollection
 .whereEqualTo("sharedByUserId", currentUser.uid)
 .get()
 .await()
 .documents

 if (sharedPostDocs.isEmpty()) {
 return@withContext emptyList<Post>()
 }

 android.util.Log.d(
 "FirebaseRepository",
 "Found ${sharedPostDocs.size} posts shared by current user"
 )

 // Get shared posts by current user
 val userSharedPosts = sharedPostDocs
 .mapNotNull { it.getString("originalPostId") }
 .toSet()

 val result = mutableListOf<Post>()

 for (sharedPostDoc in sharedPostDocs) {
 val sharedPost = sharedPostDoc.toObject(SharedPost::class.java) ?: continue

 android.util.Log.d(
 "FirebaseRepository",
 "Processing post shared by current user: ${sharedPost.id}, original post: ${sharedPost.originalPostId}"
 )

 val originalPostId = sharedPost.originalPostId

 val originalPost = getPostById(originalPostId) ?: continue

 // Create a new post object that combines the original post with sharing info
 val combinedPost = originalPost.copy(
 isSharedPost = true,
 sharedByUserId = sharedPost.sharedByUserId,
 sharedByUserName = sharedPost.sharedByUserName,
 isSharedByCurrentUser = true // Always true since these are shared by current user
 )

 result.add(combinedPost)
 }

 return@withContext result
 } catch (e: Exception) {
 android.util.Log.e(
 "FirebaseRepository",
 "Error getting posts shared by current user",
 e
 )
 return@withContext emptyList<Post>()
 }
 }

 /**
 * Share a post
 */
 suspend fun sharePost(postId: String): Boolean = withContext(Dispatchers.IO) {
 val currentUser = auth.currentUser ?: throw IllegalStateException("No user logged in")

 try {
 // Get the post to share
 val post = getPostById(postId) ?: throw IllegalStateException("Post not found")

 // Check if user has already shared this post
 val existingShareQuery = sharedPostsCollection
 .whereEqualTo("sharedByUserId", currentUser.uid)
 .whereEqualTo("originalPostId", postId)
 .get()
 .await()

 // If already shared, remove the share
 if (!existingShareQuery.isEmpty) {
 android.util.Log.d(
 "FirebaseRepository",
 "Found existing share, removing it"
 )

 val shareDoc = existingShareQuery.documents.first()
 sharedPostsCollection.document(shareDoc.id).delete().await()

 // Decrement the share count on the original post
 postsCollection.document(postId).update("shareCount", FieldValue.increment(-1))
 .await()

 return@withContext false // Indicate share was removed
 }

 // Get current user info
 val user = getCurrentUser() ?: throw IllegalStateException("Failed to get user profile")

 // Create a shared post entry
 val sharedPostId = sharedPostsCollection.document().id
 val sharedPost = SharedPost(
 id = sharedPostId,
 originalPostId = postId,
 sharedByUserId = currentUser.uid,
 sharedByUserName = user.displayName,
 sharedByUserProfilePicture = user.photoUrl,
 createdAt = Timestamp.now()
 )

 // Log the shared post creation
 android.util.Log.d(
 "FirebaseRepository",
 "Creating shared post: $sharedPostId, original: $postId, sharedBy: ${user.displayName}"
 )

 // Save the shared post
 sharedPostsCollection.document(sharedPostId).set(sharedPost).await()

 // Increment the share count on the original post
 postsCollection.document(postId).update("shareCount", FieldValue.increment(1)).await()

 return@withContext true // Indicate share was added
 } catch (e: Exception) {
 android.util.Log.e("FirebaseRepository", "Error sharing post", e)
 return@withContext false
 }
 }

 /**
 * Get shared posts from friends
 */
 private suspend fun getSharedPostsForFriends(friendIds: Set<String>): List<Post> =
 withContext(Dispatchers.IO) {
 try {
 val currentUser = auth.currentUser ?: return@withContext emptyList<Post>()

 // Get all shared posts from friends
 val sharedPostDocs = sharedPostsCollection
 .get()
 .await()
 .documents
 .filter { doc ->
 val sharedByUserId = doc.getString("sharedByUserId")
 friendIds.contains(sharedByUserId)
 }

 if (sharedPostDocs.isEmpty()) {
 return@withContext emptyList<Post>()
 }

 android.util.Log.d(
 "FirebaseRepository",
 "Found ${sharedPostDocs.size} shared post documents"
 )

 // Get shared posts by current user
 val userSharedPosts = sharedPostsCollection
 .whereEqualTo("sharedByUserId", currentUser.uid)
 .get()
 .await()
 .documents
 .mapNotNull { it.getString("originalPostId") }
 .toSet()

 android.util.Log.d(
 "FirebaseRepository",
 "Current user has shared ${userSharedPosts.size} posts: $userSharedPosts"
 )

 // Get original posts for each shared post
 val result = mutableListOf<Post>()

 for (sharedPostDoc in sharedPostDocs) {
 val sharedPost = sharedPostDoc.toObject(SharedPost::class.java) ?: continue

 android.util.Log.d(
 "FirebaseRepository",
 "Processing shared post: ${sharedPost.id}, original post: ${sharedPost.originalPostId}"
 )

 val originalPostId = sharedPost.originalPostId

 val originalPost = getPostById(originalPostId) ?: continue

 // Create a new post object that combines the original post with sharing info
 val combinedPost = originalPost.copy(
 isSharedPost = true,
 sharedByUserId = sharedPost.sharedByUserId,
 sharedByUserName = sharedPost.sharedByUserName,
 isSharedByCurrentUser = userSharedPosts.contains(originalPostId)
 )

 android.util.Log.d(
 "FirebaseRepository",
 "Added shared post with sharer: ${sharedPost.sharedByUserName}, isSharedByCurrentUser=${
 userSharedPosts.contains(
 originalPostId
 )
 }"
 )

 result.add(combinedPost)
 }

 return@withContext result
 } catch (e: Exception) {
 android.util.Log.e("FirebaseRepository", "Error getting shared posts", e)
 return@withContext emptyList<Post>()
 }
 }

 // Search for posts by content
 suspend fun searchPosts(query: String): List<Post> = withContext(Dispatchers.IO) {
 if (query.length < 2) return@withContext emptyList()

 val currentUser = auth.currentUser ?: return@withContext emptyList()

 // Save search query to history if it's not empty
 if (query.isNotEmpty()) {
 try {
 saveSearchQuery(query)
 } catch (e: Exception) {
 Log.e("FirebaseRepository", "Error saving search query: ${e.message}", e)
 }
 }

 try {
 // Get all posts
 val allPosts = postsCollection
 .get()
 .await()
 .toObjects(Post::class.java)
 .sortedByDescending { it.createdAt }

 // Get all likes by current user
 val userLikes = likesCollection
 .whereEqualTo("userId", currentUser.uid)
 .get()
 .await()
 .documents
 .mapNotNull { it.getString("postId") }
 .toSet()

 // Get user's friends to filter private posts
 val friendships = friendshipsCollection
 .whereEqualTo("userId", currentUser.uid)
 .whereEqualTo("status", "ACCEPTED")
 .get()
 .await()
 .documents
 .mapNotNull { it.getString("friendId") }
 .toSet()

 // Filter posts based on:
 // 1. Post text contains query (case insensitive)
 // 2. Privacy settings (same as in getPostsWithLikeStatus)
 val filteredPosts = allPosts.filter { post ->
 post.text.contains(query, ignoreCase = true) &&
 (!post.isPrivate || post.userId == currentUser.uid || friendships.contains(
 post.userId
 ))
 }

 // Mark posts as liked if they are in the userLikes set
 return@withContext filteredPosts.map { post ->
 post.copy(isLikedByCurrentUser = userLikes.contains(post.id))
 }
 } catch (e: Exception) {
 Log.e("FirebaseRepository", "Error searching posts: ${e.message}", e)
 return@withContext emptyList()
 }
 }

 // Comment operations
 suspend fun addComment(postId: String, text: String, imageUri: Uri?): Comment = withContext(Dispatchers.IO) {
 val currentUser = auth.currentUser ?: throw IllegalStateException("No user logged in")

 // Get the user display name
 val userDisplayName = currentUser.displayName ?: "Unknown User"

 // If image is included, try to upload to storage first
 var imageUrl: String? = null
 if (imageUri != null) {
 try {
 imageUrl = uploadImage(imageUri, "comments")
 } catch (e: Exception) {
 // Log the error but continue creating comment without image
 android.util.Log.e(
 "FirebaseRepository",
 "Failed to upload comment image: ${e.message}"
 )
 // If image upload fails, we'll proceed with creating the comment without an image
 }
 }

 val commentId = commentsCollection.document().id
 val comment = Comment(
 id = commentId,
 postId = postId,
 userId = currentUser.uid,
 userDisplayName = userDisplayName, 
 text = text,
 imageUrl = imageUrl,
 createdAt = Timestamp.now()
 )

 commentsCollection.document(commentId).set(comment).await()

 // Increment comment count
 postsCollection.document(postId).update("commentCount",
 FieldValue.increment(1)).await()

 // Create notification for the comment
 val post = getPostById(postId) ?: return@withContext comment
 val user = getCurrentUser() ?: return@withContext comment
 if (post.userId != user.id) {
 notificationRepository.createCommentNotification(post, commentId, user)
 } else {
 Log.d("FirebaseRepository", "Skipping self-notification for comment")
 }

 comment
 }

