ment.CenterVertically\n ) {\n if (isShared) {\n // Shared state - show button in a colored circular background\n Box(\n modifier = Modifier\n .background(\n color = Color(0xFFE91E63), // Hard-coded for debugging\n shape = CircleShape\n )\n .padding(4.dp)\n ) {\n Icon(\n painter = painterResource(R.drawable.ic_share),\n contentDescription = \"Share icon\",\n tint = Color.White,\n modifier = Modifier.size(16.dp)\n )\n }\n \n Spacer(modifier = Modifier.width(4.dp))\n \n Text(\n text = \"$shareCount\",\n fontSize = 16.sp,\n color = Color(0xFFE91E63), // Hard-coded for debugging\n fontWeight = FontWeight.Bold\n )\n } else {\n // Regular state\n Image(\n painter = painterResource(R.drawable.ic_share),\n contentDescription = \"Share icon\",\n modifier = Modifier\n .size(24.dp)\n .padding(end = 4.dp)\n )\n \n Text(\n text = \"$shareCount\",\n fontSize = 16.sp,\n color = LocalCustomColors.current.textPrimary\n )\n }\n }\n }\n}"}"}}]},{"role":"tool","name":"edit_file","tool_call_id":"toolu_bdrk_01G6VcAisKEEUuCVbTTd1sZz","content":"The apply model made the following changes to the file:

