ing(vertical = 4.dp, horizontal = 8.dp)\n ) {\n if (isShared) {\n // Shared state - pink background with rounded corners\n Row(\n verticalAlignment = Alignment.CenterVertically,\n modifier = Modifier\n .background(SHARED_COLOR, RoundedCornerShape(16.dp))\n .padding(horizontal = 12.dp, vertical = 6.dp)\n ) {\n Icon(\n painter = painterResource(R.drawable.ic_share),\n contentDescription = \"Share icon\",\n tint = Color.White,\n modifier = Modifier.size(18.dp)\n )\n \n Spacer(modifier = Modifier.width(8.dp))\n \n Text(\n text = \"$shareCount\",\n fontSize = 16.sp,\n color = Color.White,\n fontWeight = FontWeight.Bold\n )\n }\n } else {\n // Not shared state - simple row\n Row(\n verticalAlignment = Alignment.CenterVertically,\n modifier = Modifier\n .border(\n width = 1.dp,\n color = LocalCustomColors.current.textSecondary,\n shape = RoundedCornerShape(16.dp)\n )\n .padding(horizontal = 12.dp, vertical = 6.dp)\n ) {\n Icon(\n painter = painterResource(R.drawable.ic_share),\n contentDescription = \"Share icon\",\n tint = LocalCustomColors.current.textPrimary,\n modifier = Modifier.size(18.dp)\n )\n \n Spacer(modifier = Modifier.width(8.dp))\n \n Text(\n text = \"$shareCount\",\n fontSize = 16.sp,\n color = LocalCustomColors.current.textPrimary\n )\n }\n }\n }\n}"}"}}]},{"role":"tool","name":"edit_file","tool_call_id":"toolu_bdrk_01MvpDdSz8LrrZVxbFvCb3L4","content":"The apply model made the following changes to the file:

