@Composable
fun PostItemDetailed(
 modifier: Modifier = Modifier,
 authorName: String,
 content: String,
 imageUrl: String? = null,
 videoUrl: String? = null,
 hasVideo: Boolean = false,
 likeCount: Int = 0,
 isLikedByCurrentUser: Boolean = false,
 commentCount: Int = 0,
 shareCount: Int = 0,
