 onHideClick: ((String) -> Unit)? = null,
 onEditClick: ((Post) -> Unit)? = null
) {
 Surface(
 modifier = modifier
 .fillMaxWidth()
 .clip(RoundedCornerShape(16.dp)),
 tonalElevation = 2.dp,
 color = LocalCustomColors.current.secondaryBackground
 ) {
 Column(
 modifier = Modifier
 .fillMaxWidth()
 .padding(horizontal = 8.dp)
 ) {
 // Post shared information
 if (isSharedPost) {
 Row(
 verticalAlignment = Alignment.CenterVertically,
 modifier = Modifier.padding(start = 16.dp, top = 8.dp, end = 16.dp)
 ) {
 Image(
 painter = painterResource(R.drawable.ic_share),
 contentDescription = "Share icon",
 modifier = Modifier
 .size(16.dp)
 .padding(end = 4.dp)
 )

 Text(
 text = stringResource(R.string.shared_post, sharedByUserName),
 fontSize = 14.sp,
 fontWeight = FontWeight.Bold,
 color = LocalCustomColors.current.textSecondary,
 modifier = Modifier.padding(start = 4.dp)
 )
 }

 // Log to verify render
 android.util.Log.d(
 "PostItemDetailed",
 "Rendering shared post info: sharer=$sharedByUserName"
 )
 }

 // Author info row
 Row(
 verticalAlignment = Alignment.CenterVertically,
 modifier = Modifier.padding(start = 16.dp, top = 16.dp, end = 16.dp, bottom = 8.dp)
 ) {
 // Profile picture
 Box(
 modifier = Modifier
 .size(40.dp)
 .clip(CircleShape)
 .background(MaterialTheme.colorScheme.primary.copy(alpha = 0.2f))
 .clickable {
 if (onProfileClick != null) {
 onProfileClick()
 } else if (userId != null && navController != null) {
 Navigation.navigateToUserProfile(userId, navController)
 }
 }
 ) {
 if (profilePictureUrl != null) {
 AsyncImage(
 model = profilePictureUrl,
 contentDescription = "Profile picture",
 contentScale = ContentScale.Crop,
 modifier = Modifier.fillMaxWidth()
 )
 } else {
 // User initial as placeholder - use first letter of display name
 Icon(
 imageVector = Icons.Default.Person,
 contentDescription = null,
 modifier = Modifier.align(Alignment.Center)
 )
 }
 }

 Spacer(modifier = Modifier.width(8.dp))

 // Author name - also clickable to go to profile
 Row(
 verticalAlignment = Alignment.CenterVertically
 ) {
 Text(
 text = authorName,
 fontSize = 20.sp,
 fontWeight = FontWeight.Bold,
 color = LocalCustomColors.current.textPrimary,
 modifier = Modifier
 .padding(top = 4.dp, start = 2.dp)
 .clickable {
 if (onProfileClick != null) {
 onProfileClick()
 } else if (userId != null && navController != null) {
 Navigation.navigateToUserProfile(userId, navController)
 }
 }
 )

 // Visibility icon
 Spacer(modifier = Modifier.width(4.dp))

 post?.let {
 Icon(
 painter = when (it.visibility) {
 PostVisibility.PUBLIC -> painterResource(id = R.drawable.ic_language)
 PostVisibility.FRIENDS_ONLY -> painterResource(id = R.drawable.ic_friends)
 PostVisibility.PRIVATE -> painterResource(id = R.drawable.ic_lock)
 },
 contentDescription = "Post visibility",
 tint = LocalCustomColors.current.textSecondary,
 modifier = Modifier.size(16.dp)
 )
 }
 }

 Spacer(modifier = Modifier.weight(1f))

 // Add dropdown menu for post actions
 var showMenu by remember { mutableStateOf(false) }

 Box {
 IconButton(
 onClick = { showMenu = true },
 modifier = Modifier.size(40.dp)
 ) {
 Icon(
 imageVector = Icons.Default.MoreVert,
 contentDescription = "More options",
 tint = LocalCustomColors.current.textPrimary
 )
 }

 val currentUser = FirebaseAuth.getInstance().currentUser
 val isPostOwner = currentUser?.uid == userId

 DropdownMenu(
 expanded = showMenu,
 onDismissRequest = { showMenu = false }
 ) {
 if (isPostOwner) {
 DropdownMenuItem(
 text = { Text("Edit Post") },
 onClick = {
 post?.let {
 onEditClick?.invoke(it)
 }
 showMenu = false
 }
 )

 DropdownMenuItem(
 text = { Text("Delete Post") },
 onClick = {
 post?.id?.let { postId ->
 onDeleteClick?.invoke(postId)
 }
 showMenu = false
 }
 )
 } else {
 DropdownMenuItem(
 text = { Text("Hide Post") },
 onClick = {
 post?.id?.let { postId ->
 onHideClick?.invoke(postId)
 }
 showMenu = false
 }
 )
 }
 }
 }
 }

 // Post content
 Text(
 text = content,
 fontSize = 20.sp,
 color = LocalCustomColors.current.textPrimary,
 modifier = Modifier.padding(horizontal = 16.dp, vertical = 8.dp)
 )

 // Display image or video if available
 if (hasVideo && videoUrl != null) {
 var showFullScreenVideo by remember { mutableStateOf(false) }

 VideoPlayer(
 videoUrl = videoUrl,
 modifier = Modifier
 .fillMaxWidth()
 .height(220.dp)
 .padding(12.dp)
 .clip(RoundedCornerShape(16.dp))
 .clickable { showFullScreenVideo = true }
 )

 if (showFullScreenVideo) {
 MediaViewerScreen(
 mediaUrl = videoUrl,
 isVideo = true,
 onDismiss = { showFullScreenVideo = false }
 )
 }
 } else if (imageUrl != null) {
 var showFullScreenImage by remember { mutableStateOf(false) }

 Box(
 modifier = Modifier
 .fillMaxWidth()
 .height(220.dp)
 .padding(bottom = 5.dp)
 .clickable { showFullScreenImage = true }
 ) {
 CircularProgressIndicator(
 modifier = Modifier
 .size(40.dp)
 .align(Alignment.Center)
 )

 AsyncImage(
 model = if (imageUrl.startsWith("content:") || imageUrl.startsWith("file:")) {
 Uri.parse(imageUrl)
 } else {
 imageUrl
 },
 contentDescription = "Post image",
 contentScale = ContentScale.Fit,
 modifier = Modifier
 .fillMaxSize()
 .padding(12.dp)
 .clip(RoundedCornerShape(16.dp)),
 error = painterResource(id = R.drawable.ic_error_image),
 placeholder = painterResource(id = R.drawable.ic_error_image),
 onLoading = {
 android.util.Log.d("PostItemDetailed", "Loading image: $imageUrl")
 },
 onError = {
 android.util.Log.e(
 "PostItemDetailed",
 "Error loading image: $imageUrl, error: $it"
 )
 },
 onSuccess = {
 android.util.Log.d(
 "PostItemDetailed",
 "Successfully loaded image: $imageUrl"
 )
 }
 )
 }

 // Show full screen image viewer when clicked
 if (showFullScreenImage) {
 MediaViewerScreen(
 mediaUrl = imageUrl,
 isVideo = false,
 onDismiss = { showFullScreenImage = false }
 )
 }
 }

 HorizontalDivider(
 modifier = Modifier.padding(horizontal = 8.dp),
 color = Color.LightGray,
 thickness = 0.5.dp
 )

 // Action buttons row
 Row(
 modifier = Modifier
 .fillMaxWidth()
 .padding(horizontal = 4.dp, vertical = 4.dp),
 verticalAlignment = Alignment.CenterVertically,
 horizontalArrangement = androidx.compose.foundation.layout.Arrangement.SpaceAround
 ) {
 // Like button
 Box(
 modifier = Modifier
 .weight(1f, fill = false)
 .padding(vertical = 8.dp, horizontal = 8.dp)
