package com.example.kiendatn2.data

import com.google.firebase.Timestamp

enum class PostVisibility {
 PUBLIC,
 FRIENDS_ONLY,
 PRIVATE
}

data class Post(
 val id: String = "",
 val userId: String = "",
 val userDisplayName: String = "",
 val userProfilePicture: String? = null,
 val text: String = "",
