package com.example.kiendatn2.repository

import android.net.Uri
import android.util.Log
import com.example.kiendatn2.data.Comment
import com.example.kiendatn2.data.FriendshipStatus
import com.example.kiendatn2.data.Notification
import com.example.kiendatn2.data.Post
import com.example.kiendatn2.data.User
import com.google.firebase.Timestamp
import com.google.firebase.auth.FirebaseAuth
import com.google.firebase.firestore.FieldValue
import com.google.firebase.firestore.FirebaseFirestore
import com.google.firebase.firestore.Query
import com.google.firebase.storage.FirebaseStorage
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.tasks.await
import kotlinx.coroutines.withContext

class FirebaseRepository {
 private val auth = FirebaseAuth.getInstance()
 private val firestore = FirebaseFirestore.getInstance()
 private val storage = FirebaseStorage.getInstance()

 private val usersCollection = firestore.collection("users")
 private val postsCollection = firestore.collection("posts")
 private val commentsCollection = firestore.collection("comments")
 private val likesCollection = firestore.collection("likes")
 private val commentLikesCollection = firestore.collection("commentLikes")
 private val friendshipsCollection = firestore.collection("friendships")
 private val notificationRepository = NotificationRepository()

 // Current user operations
 fun getCurrentFirebaseUser() = auth.currentUser

 suspend fun createUserProfile(user: User) = withContext(Dispatchers.IO) {
 val currentUser = auth.currentUser ?: throw IllegalStateException("No user logged in")
 val userData = user.copy(id = currentUser.uid, email = currentUser.email ?: "")
 usersCollection.document(currentUser.uid).set(userData).await()
 }

 suspend fun getCurrentUser(): User? = withContext(Dispatchers.IO) {
 try {
 val currentUser = auth.currentUser ?: return@withContext null
 val userDoc = usersCollection.document(currentUser.uid).get().await()

 // Debug log to check what we're getting from Firestore
 if (!userDoc.exists()) {
 Log.e(
 "FirebaseRepository",
 "User document doesn't exist for UID: ${currentUser.uid}"
 )
 return@withContext null
 } else {
 Log.d("FirebaseRepository", "Retrieved user doc data: ${userDoc.data}")
 }

 val user = userDoc.toObject(User::class.java)

 // If we got a user but it doesn't have an ID field populated, update it
 if (user != null && user.id.isBlank()) {
 Log.d(
 "FirebaseRepository",
 "User exists but has blank ID, using UID: ${currentUser.uid}"
 )
 return@withContext user.copy(id = currentUser.uid)
 }

 return@withContext user
 } catch (e: Exception) {
 Log.e("FirebaseRepository", "Error getting current user", e)
 throw e
 }
 }

 // Password change operation
 suspend fun changePassword(currentPassword: String, newPassword: String): Result<Unit> =
 withContext(Dispatchers.IO) {
 try {
 val currentUser = auth.currentUser ?: return@withContext Result.failure(
 IllegalStateException("No user logged in")
 )
 val email = currentUser.email ?: return@withContext Result.failure(
 IllegalStateException("User has no email")
 )

 // Re-authenticate user first
 val credential =
 com.google.firebase.auth.EmailAuthProvider.getCredential(email, currentPassword)
 currentUser.reauthenticate(credential).await()

 // Then update password
 currentUser.updatePassword(newPassword).await()
 return@withContext Result.success(Unit)
 } catch (e: Exception) {
 Log.e("FirebaseRepository", "Error changing password", e)
 return@withContext Result.failure(e)
 }
 }

 // User profile operations
 suspend fun updateUserProfile(displayName: String, bio: String?, photoUri: Uri?): User = withContext(Dispatchers.IO) {
 val currentUser = auth.currentUser ?: throw IllegalStateException("No user logged in")

 // Upload photo if provided - handle potential failures
 var photoUrl = getCurrentUser()?.photoUrl
 if (photoUri != null) {
 try {
 photoUrl = uploadImage(photoUri, "profiles")
 } catch (e: Exception) {
 // Log error but continue with profile update without changing photo
 Log.e(
 "FirebaseRepository",
 "Failed to upload profile photo: ${e.message}"
 )
 }
 }

 // Create updated user data
 val userData = mapOf(
 "displayName" to displayName,
 "bio" to bio,
 "photoUrl" to photoUrl
 )

 // Update user document
 usersCollection.document(currentUser.uid).update(userData).await()

 // Update profile picture and display name in all user's posts
 updateUserPostsProfilePicture(photoUrl, displayName)

 // Update display name in all user's comments
 updateUserCommentsDisplayName(displayName)

 // Return updated user
 getCurrentUser() ?: throw IllegalStateException("Failed to get updated user")
 }

 suspend fun updateUserProfileWithCloudinaryUrl(
 displayName: String,
 bio: String?,
 cloudinaryUrl: String?
 ): User = withContext(Dispatchers.IO) {
 val currentUser = auth.currentUser ?: throw IllegalStateException("No user logged in")

 // Create updated user data
 val userData = mapOf(
 "displayName" to displayName,
 "bio" to bio,
 "photoUrl" to cloudinaryUrl
 )

 // Update user document
 usersCollection.document(currentUser.uid).update(userData).await()

 // Update profile picture and display name in all user's posts
 updateUserPostsProfilePicture(cloudinaryUrl, displayName)

 // Update display name in all user's comments
 updateUserCommentsDisplayName(displayName)

 // Return updated user
 getCurrentUser() ?: throw IllegalStateException("Failed to get updated user")
 }

 /**
 * Update the profile picture URL and display name in all posts by the current user
 */
 private suspend fun updateUserPostsProfilePicture(
 profilePictureUrl: String?,
 displayName: String? = null
 ) =
 withContext(Dispatchers.IO) {
 try {
 val currentUser = auth.currentUser ?: return@withContext

 // Get all posts by this user
 val userPosts = postsCollection
 .whereEqualTo("userId", currentUser.uid)
 .get()
 .await()

 if (!userPosts.isEmpty) {
 val batch = firestore.batch()

 // Update each post with the new profile picture URL and/or display name
 for (postDoc in userPosts.documents) {
 // Check what fields need to be updated
 if (profilePictureUrl != null && displayName != null) {
 // Update both profile picture and display name
 batch.update(
 postDoc.reference,
 mapOf(
 "userProfilePicture" to profilePictureUrl,
 "userDisplayName" to displayName
 )
 )
 } else if (profilePictureUrl != null) {
 // Update only profile picture
 batch.update(
 postDoc.reference,
 "userProfilePicture",
 profilePictureUrl
 )
 } else if (displayName != null) {
 // Update only display name
 batch.update(
 postDoc.reference,
 "userDisplayName",
 displayName
 )
 }
 }

 // Commit all updates in a single batch
 batch.commit().await()

 // Create a detailed log message
 val updatedFields = mutableListOf<String>()
 if (profilePictureUrl != null) updatedFields.add("profile picture")
 if (displayName != null) updatedFields.add("display name")

 android.util.Log.d(
 "FirebaseRepository",
 "Updated ${updatedFields.joinToString(" and ")} in ${userPosts.size()} posts"
 )
 }
 } catch (e: Exception) {
 // Create a detailed error message
 val updatedFields = mutableListOf<String>()
 if (profilePictureUrl != null) updatedFields.add("profile picture")
 if (displayName != null) updatedFields.add("display name")
 android.util.Log.e(
 "FirebaseRepository",
 "Error updating ${updatedFields.joinToString(" and ")} in posts: ${e.message}",
 e
 )
 }
 }

 /**
 * Update the display name in all comments and replies by the current user
 */
 private suspend fun updateUserCommentsDisplayName(displayName: String) =
 withContext(Dispatchers.IO) {
 try {
 val currentUser = auth.currentUser ?: return@withContext

 // Get all comments by this user
 val userComments = commentsCollection
 .whereEqualTo("userId", currentUser.uid)
 .get()
 .await()

 // Count total updated documents
 var totalUpdated = 0

 if (!userComments.isEmpty) {
 val batch = firestore.batch()

 // Update each comment with the new display name
 for (commentDoc in userComments.documents) {
 batch.update(
 commentDoc.reference,
 "userDisplayName",
 displayName
 )
 }

 // Commit all updates in a single batch
 batch.commit().await()
 totalUpdated += userComments.size()

 }

 // Get all replies by this user (also stored in comments collection, but with parentCommentId field)
 val userReplies = commentsCollection
 .whereEqualTo("userId", currentUser.uid)
 .whereGreaterThan("parentCommentId", "") // Filter for replies
 .get()
 .await()

 if (!userReplies.isEmpty) {
 val batch = firestore.batch()

 // Update each reply with the new display name
 for (replyDoc in userReplies.documents) {
 batch.update(
 replyDoc.reference,
 "userDisplayName",
 displayName
 )
 }

 // Commit all updates in a single batch
 batch.commit().await()
 totalUpdated += userReplies.size()
 }

 // Log total updates
 android.util.Log.d(
 "FirebaseRepository",
 "Updated display name in $totalUpdated comments and replies"
 )
 } catch (e: Exception) {
 android.util.Log.e(
 "FirebaseRepository",
 "Error updating display name in comments and replies: ${e.message}",
 e
 )
 }
 }

