package com.example.kiendatn2.service

import android.content.Context
import android.graphics.Bitmap
import android.net.Uri
import android.util.Log
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import org.json.JSONObject
import java.io.ByteArrayOutputStream
import java.io.File
import java.io.FileOutputStream
import java.io.IOException
import java.util.UUID
import okhttp3.MediaType.Companion.toMediaType
import okhttp3.MultipartBody
import okhttp3.OkHttpClient
import okhttp3.Request
import okhttp3.RequestBody.Companion.asRequestBody

/**
 * CloudinaryManager - Simple implementation to handle media uploads to Cloudinary
 * using OkHttp directly
 */
class CloudinaryManager {

 companion object {
 private const val TAG = "CloudinaryManager"
 private const val CLOUDINARY_IMAGE_URL = "https://api.cloudinary.com/v1_1/%s/image/upload"
 private const val CLOUDINARY_VIDEO_URL = "https://api.cloudinary.com/v1_1/%s/video/upload"

 private var cloudName: String = ""
 private var uploadPreset: String = ""
 private var isInitialized = false

 /**
 * Check if CloudinaryManager is properly initialized
 * @return true if initialized, false otherwise
 */
 fun isInitialized(): Boolean {
 return isInitialized && cloudName.isNotBlank() && uploadPreset.isNotBlank()
 }

 /**
 * Initialize Cloudinary with your account credentials
 * @return true if initialization was successful
 */
 fun initialize(cloudNameValue: String, uploadPresetValue: String): Boolean {
 if (cloudNameValue.isBlank() || uploadPresetValue.isBlank()) {
 Log.e(TAG, "CloudinaryManager initialization failed: empty credentials")
 isInitialized = false
 return false
 }

 cloudName = cloudNameValue
 uploadPreset = uploadPresetValue
 isInitialized = true
 Log.d(TAG, "CloudinaryManager initialized with cloud name: $cloudName")
 return true
 }
 }

 private val client = OkHttpClient()

 /**
 * Upload a file to Cloudinary
 * @param file File to upload
 * @param isVideo Whether the file is a video (true) or image (false)
 * @return URL of the uploaded media
 * @throws IOException if upload fails
 */
 @Throws(IOException::class)
 suspend fun uploadFile(file: File, isVideo: Boolean = false): String =
 withContext(Dispatchers.IO) {
 if (!isInitialized()) {
 throw IOException("CloudinaryManager not initialized properly. Make sure to call initialize() with valid credentials.")
 }

 try {
 val mediaType = if (isVideo) "video/*" else "image/*"
 val uploadUrl = if (isVideo) {
 String.format(CLOUDINARY_VIDEO_URL, cloudName)
 } else {
 String.format(CLOUDINARY_IMAGE_URL, cloudName)
 }

 val requestBody = MultipartBody.Builder()
 .setType(MultipartBody.FORM)
 .addFormDataPart(
 "file",
 file.name,
 file.asRequestBody(mediaType.toMediaType())
 )
 .addFormDataPart("upload_preset", uploadPreset)
 .addFormDataPart("folder", "app_uploads")
 .build()

 val request = Request.Builder()
 .url(uploadUrl)
 .post(requestBody)
 .build()

 val response = client.newCall(request).execute()
 if (!response.isSuccessful) {
 throw IOException("Unexpected response code: ${response.code}")
 }

 val responseBody = response.body?.string() ?: throw IOException("Empty response body")
 val json = JSONObject(responseBody)
 val secureUrl = json.getString("secure_url")

 Log.d(TAG, "Upload successful: $secureUrl")
 return@withContext secureUrl

 } catch (e: Exception) {
 Log.e(TAG, "Upload failed: ${e.message}", e)
 throw IOException("Media upload failed: ${e.message}", e)
 }
 }

 /**
 * Upload a bitmap to Cloudinary
 * @param context Context
 * @param bitmap Bitmap to upload
 * @return URL of the uploaded image
 * @throws IOException if upload fails
 */
 @Throws(IOException::class)
 suspend fun uploadBitmap(context: Context, bitmap: Bitmap): String {
 val file = bitmapToFile(context, bitmap)
 val result = uploadFile(file)
 // Delete the temporary file
 file.delete()
 return result
 }

 /**
 * Upload media from a Uri
 * @param context Context
 * @param uri Uri of media to upload
 * @param isVideo Whether the media is a video (true) or image (false)
 * @return URL of the uploaded media
 * @throws IOException if upload fails
 */
 @Throws(IOException::class)
 suspend fun uploadFromUri(context: Context, uri: Uri, isVideo: Boolean = false): String =
 withContext(Dispatchers.IO) {
 if (!isInitialized()) {
 throw IOException("CloudinaryManager not initialized properly. Make sure to call initialize() with valid credentials.")
 }

 var tempFile: File? = null
 try {
 val inputStream = context.contentResolver.openInputStream(uri)
 ?: throw IOException("Failed to open input stream for URI: $uri")

 // Create a temporary file with appropriate extension
 val extension = if (isVideo) ".mp4" else ".jpg"
 tempFile = File.createTempFile("upload_", extension, context.cacheDir)

 inputStream.use { stream ->
 FileOutputStream(tempFile).use { output ->
 stream.copyTo(output)
 }
 }

 // Upload the file
 return@withContext uploadFile(tempFile, isVideo)
 } catch (e: Exception) {
 Log.e(TAG, "Upload from URI failed: ${e.message}", e)
 throw IOException("Media upload failed: ${e.message}", e)
 } finally {
 // Always delete the temporary file, even if upload fails
 try {
 tempFile?.let {
 if (it.exists()) {
 val deleted = it.delete()
 if (!deleted) {
 Log.w(
 TAG,
 "Failed to delete temporary file: ${tempFile.absolutePath}"
 )
 }
 }
 }
 } catch (e: Exception) {
 Log.e(TAG, "Error deleting temporary file", e)
 }
 }
 }

 /**
 * Convert a bitmap to a file in the cache directory
 */
 private fun bitmapToFile(context: Context, bitmap: Bitmap): File {
 if (!isInitialized()) {
 throw IOException("CloudinaryManager not initialized properly. Make sure to call initialize() with valid credentials.")
 }

 val filename = "image_${UUID.randomUUID()}.jpg"
 val file = File(context.cacheDir, filename)

 try {
 // For large bitmaps, write directly to file to avoid OutOfMemoryError
 if (bitmap.width * bitmap.height > 1024 * 1024) { // Large image (>1MP)
 FileOutputStream(file).use { fos ->
 bitmap.compress(Bitmap.CompressFormat.JPEG, 85, fos)
 fos.flush()
 }
 } else {
 // For smaller images, use ByteArrayOutputStream for better performance
 ByteArrayOutputStream().use { bos ->
 bitmap.compress(Bitmap.CompressFormat.JPEG, 90, bos)
 FileOutputStream(file).use { fos ->
 fos.write(bos.toByteArray())
 fos.flush()
 }
 }
 }
 return file
 } catch (e: IOException) {
 Log.e(TAG, "Error saving bitmap to file: ${e.message}", e)
 throw e
 }
 }
}
