@Composable
fun PostItem(
 modifier: Modifier = Modifier,
 post: Post,
 postViewModel: PostViewModel,
 navController: NavController? = null
) {
 // State to track if post is being loaded for comments
 var isLoading by remember { mutableStateOf(false) }

 // Log image URL for debugging
 LaunchedEffect(post.id) {
 android.util.Log.d(
 "PostItem",
 "Post ID: ${post.id}, Has image: ${post.imageUrl != null}, Has video: ${post.hasVideo}, Video URL: ${post.videoUrl ?: "none"}"
 )
 }

 PostItemDetailed(
 modifier = modifier,
 authorName = post.userDisplayName,
 profilePictureUrl = post.userProfilePicture,
 content = post.text,
 imageUrl = post.imageUrl,
 videoUrl = post.videoUrl,
 hasVideo = post.hasVideo,
 likeCount = post.likeCount,
 commentCount = post.commentCount,
 shareCount = post.shareCount,
 isLikedByCurrentUser = post.isLikedByCurrentUser,
 userId = post.userId,
 navController = navController,
 onLikeClick = { postViewModel.toggleLike(post.id) },
 onCommentClick = {
 isLoading = true
 // Load post in the next frame to avoid UI glitches
 postViewModel.loadPostById(post.id)
 },
 onShareClick = { /* Implement share functionality */ }
 )

 // Show loading indicator if we're loading comments
 if (isLoading) {
 Box(
 modifier = Modifier.fillMaxSize(),
 contentAlignment = Alignment.Center
 ) {
 CircularProgressIndicator(
 modifier = Modifier.size(24.dp)
 )
 }
 }
}
