@Composable
fun PostItemDetailed(
 modifier: Modifier = Modifier,
 authorName: String,
 content: String,
 imageUrl: String? = null,
 videoUrl: String? = null,
 hasVideo: Boolean = false,
 likeCount: Int = 0,
 isLikedByCurrentUser: Boolean = false,
 commentCount: Int = 0,
 shareCount: Int = 0,
 profilePictureUrl: String? = null,
 onLikeClick: () -> Unit = {},
 onCommentClick: () -> Unit = {},
 onShareClick: () -> Unit = {},
 userId: String? = null,
 navController: NavController? = null,
 onProfileClick: (() -> Unit)? = null
) {
 Surface(
 modifier = modifier
 .fillMaxWidth()
 .clip(RoundedCornerShape(16.dp)),
 tonalElevation = 2.dp,
 color = LocalCustomColors.current.secondaryBackground
 ) {
 Column(
 modifier = Modifier.fillMaxWidth().padding(horizontal = 8.dp)
 ) {
 // Author info row
 Row(
 verticalAlignment = Alignment.CenterVertically,
 modifier = Modifier.padding(start = 16.dp, top = 16.dp, end = 16.dp, bottom = 8.dp)
 ) {
 // Profile picture
 Box(
 modifier = Modifier
 .size(40.dp)
 .clip(CircleShape)
 .background(MaterialTheme.colorScheme.primary.copy(alpha = 0.2f))
 .clickable {
 if (onProfileClick != null) {
 onProfileClick()
 } else if (userId != null && navController != null) {
 Navigation.navigateToUserProfile(userId, navController)
 }
 }
 ) {
 if (profilePictureUrl != null) {
 AsyncImage(
 model = profilePictureUrl,
 contentDescription = "Profile picture",
 contentScale = ContentScale.Crop,
 modifier = Modifier.fillMaxWidth()
 )
 } else {
 // User initial as placeholder - use first letter of display name
 Icon(
 imageVector = Icons.Default.Person,
 contentDescription = null,
 modifier = Modifier.align(Alignment.Center)
 )
 }
 }

 Spacer(modifier = Modifier.width(8.dp))

 // Author name - also clickable to go to profile
 Text(
 text = authorName,
 fontSize = 20.sp,
 fontWeight = FontWeight.Bold,
 color = LocalCustomColors.current.textPrimary,
 modifier = Modifier
 .padding(top = 4.dp, start = 2.dp)
 .clickable {
 if (onProfileClick != null) {
 onProfileClick()
 } else if (userId != null && navController != null) {
 Navigation.navigateToUserProfile(userId, navController)
 }
 }
 )
 }

 // Post content
 Text(
 text = content,
 fontSize = 20.sp,
 color = LocalCustomColors.current.textPrimary,
 modifier = Modifier.padding(horizontal = 16.dp, vertical = 8.dp)
 )

 // Display image or video if available
 if (hasVideo && videoUrl != null) {
 // Display video player
 VideoPlayer(
 videoUrl = videoUrl,
 modifier = Modifier
 .fillMaxWidth()
 .height(220.dp)
 .padding(12.dp)
 .clip(RoundedCornerShape(16.dp))
 )
 } else if (imageUrl != null) {
 // Display image
 Box(
 modifier = Modifier
 .fillMaxWidth()
 .height(220.dp)
 .padding(bottom = 5.dp)
 ) {
 CircularProgressIndicator(
 modifier = Modifier
 .size(40.dp)
 .align(Alignment.Center)
 )

 AsyncImage(
 model = if (imageUrl.startsWith("content:") || imageUrl.startsWith("file:")) {
 Uri.parse(imageUrl)
 } else {
 imageUrl
 },
 contentDescription = "Post image",
 contentScale = ContentScale.Fit,
 modifier = Modifier
 .fillMaxSize()
 .padding(12.dp)
 .clip(RoundedCornerShape(16.dp)),
 error = painterResource(id = R.drawable.ic_error_image),
 placeholder = painterResource(id = R.drawable.ic_error_image),
 onLoading = {
 android.util.Log.d("PostItemDetailed", "Loading image: $imageUrl")
 },
 onError = {
 android.util.Log.e(
 "PostItemDetailed",
 "Error loading image: $imageUrl, error: $it"
 )
 },
 onSuccess = {
 android.util.Log.d(
 "PostItemDetailed",
 "Successfully loaded image: $imageUrl"
 )
 }
 )
 }
 }

 HorizontalDivider(
 modifier = Modifier.padding(horizontal = 8.dp),
 color = Color.LightGray,
 thickness = 0.5.dp
 )

 // Action buttons row
 Row(
 modifier = Modifier
 .fillMaxWidth()
 .padding(horizontal = 4.dp, vertical = 4.dp),
 verticalAlignment = Alignment.CenterVertically,
 horizontalArrangement = androidx.compose.foundation.layout.Arrangement.SpaceAround
 ) {
 // Like button
 Box(
 modifier = Modifier
 .weight(1f, fill = false)
 .padding(vertical = 8.dp, horizontal = 8.dp)
 .clickable {
 onLikeClick()
 },
 contentAlignment = Alignment.CenterStart
 ) {
 Row(
 verticalAlignment = Alignment.CenterVertically
 ) {
 Image(
 painter = painterResource(
 if (isLikedByCurrentUser) R.drawable.ic_like_filled
 else R.drawable.ic_like
 ),
 contentDescription = "Like icon",
 modifier = Modifier
 .size(24.dp)
 .padding(end = 4.dp)
 )

 Text(
 text = "$likeCount",
 fontSize = 16.sp,
 color = if (isLikedByCurrentUser) LocalCustomColors.current.textIsLiked else LocalCustomColors.current.textPrimary,
 modifier = Modifier
 )
 }
 }

 // Comment button
 Box(
 modifier = Modifier
 .weight(1f, fill = false)
 .padding(vertical = 8.dp, horizontal = 8.dp)
 .clickable {
 onCommentClick()
 },
 contentAlignment = Alignment.CenterStart
 ) {
 Row(
 verticalAlignment = Alignment.CenterVertically
 ) {
 Image(
 painter = painterResource(R.drawable.ic_comment),
 contentDescription = "Comment icon",
 modifier = Modifier
 .size(24.dp)
 .padding(end = 4.dp)
 )

 Text(
 text = "$commentCount",
 fontSize = 16.sp,
 color = LocalCustomColors.current.textPrimary,
 modifier = Modifier
 )
 }
 }

 // Share button
 Box(
 modifier = Modifier
 .weight(1f, fill = false)
 .padding(vertical = 8.dp, horizontal = 8.dp)
 .clickable {
 onShareClick()
 },
 contentAlignment = Alignment.CenterStart
 ) {
 Row(
 verticalAlignment = Alignment.CenterVertically
 ) {
 Image(
 painter = painterResource(R.drawable.ic_share),
 contentDescription = "Share icon",
 modifier = Modifier
 .size(24.dp)
 .padding(end = 4.dp)
 )

 Text(
 text = "$shareCount",
 fontSize = 16.sp,
 color = LocalCustomColors.current.textPrimary,
 modifier = Modifier
 )
 }
 }
 }

 // Optional bottom padding for better spacing
 Spacer(modifier = Modifier.height(8.dp))
 }
 }
}

