 suspend fun getPosts(): List<Post> = withContext(Dispatchers.IO) {
 postsCollection
 .orderBy("createdAt", Query.Direction.DESCENDING)
 .get()
 .await()
 .toObjects(Post::class.java)
 }

 // Add function to check if posts are liked by current user
 suspend fun getPostsWithLikeStatus(): List<Post> = withContext(Dispatchers.IO) {
 val currentUser = auth.currentUser ?: return@withContext emptyList<Post>()

 try {
 // Get all posts
 val posts = postsCollection
 .get()
 .await()
 .toObjects(Post::class.java)
 .sortedByDescending { it.createdAt }

 // Get all likes by current user
 val userLikes = likesCollection
 .whereEqualTo("userId", currentUser.uid)
 .get()
 .await()
 .documents
 .map { it.getString("postId") ?: "" }
 .toSet()

 // Get user's friends to filter private posts
 val friendships = friendshipsCollection
 .whereEqualTo("userId", currentUser.uid)
 .whereEqualTo("status", "ACCEPTED")
 .get()
 .await()
 .documents
 .mapNotNull { it.getString("friendId") }
 .toSet()

 // Get posts shared by the current user
 val userSharedPosts = sharedPostsCollection
 .whereEqualTo("sharedByUserId", currentUser.uid)
 .get()
 .await()
 .documents
 .mapNotNull { it.getString("originalPostId") }
 .toSet()

 // Debug post image URLs
 posts.forEach { post ->
 if (post.imageUrl != null) {
 android.util.Log.d(
 "FirebaseRepository",
 "Post ID: ${post.id}, Image URL: ${post.imageUrl}"
 )
 try {
 // Try to validate the image URL by checking if the file exists
 val storageRef = storage.getReferenceFromUrl(post.imageUrl!!)
 android.util.Log.d("FirebaseRepository", "Storage path: ${storageRef.path}")
 } catch (e: Exception) {
 android.util.Log.e(
 "FirebaseRepository",
 "Invalid image URL: ${post.imageUrl}",
 e
 )
 }
 }
 }

 // Filter posts based on privacy settings:
 // 1. Show public posts from everyone
 // 2. Show private posts only from friends and self
 val filteredPosts = posts.filter { post ->
 !post.isPrivate || // Public posts are visible to everyone
 post.userId == currentUser.uid || // User's own posts are always visible
 friendships.contains(post.userId) // Friend's private posts are visible
 }

 // Mark posts as liked if they are in the userLikes set
 // and mark posts as shared by current user
 return@withContext filteredPosts.map { post ->
 post.copy(
 isLikedByCurrentUser = userLikes.contains(post.id),
 isSharedByCurrentUser = userSharedPosts.contains(post.id)
 )
 }
 } catch (e: Exception) {
 // Fallback in case of errors
 return@withContext emptyList()
 }
 }

 // Add function to get posts from friends
 suspend fun getFriendsPostsWithLikeStatus(): List<Post> = withContext(Dispatchers.IO) {
 val currentUser = auth.currentUser ?: return@withContext emptyList<Post>()

 try {
 // First get all friendship connections - Get friendships both as sender and receiver
 val senderFriendships = friendshipsCollection
 .whereEqualTo("senderId", currentUser.uid)
 .whereEqualTo("status", FriendshipStatus.ACCEPTED.name)
 .get()
 .await()
 .documents
 .mapNotNull { it.getString("receiverId") }
 .toSet()

 val receiverFriendships = friendshipsCollection
 .whereEqualTo("receiverId", currentUser.uid)
 .whereEqualTo("status", FriendshipStatus.ACCEPTED.name)
 .get()
 .await()
 .documents
 .mapNotNull { it.getString("senderId") }
 .toSet()

 // Combine both friendship lists
 val friendships = senderFriendships + receiverFriendships

 if (friendships.isEmpty()) {
 android.util.Log.d(
 "FirebaseRepository",
 "User has no friends, returning empty list"
 )
 return@withContext emptyList()
 }

 android.util.Log.d("FirebaseRepository", "Found ${friendships.size} friends")

 // Debug - Log friend IDs
 friendships.forEach { friendId ->
 android.util.Log.d("FirebaseRepository", "Friend ID: $friendId")
 }

 // Get all posts
 val allPosts = postsCollection
 .get()
 .await()
 .toObjects(Post::class.java)

 android.util.Log.d("FirebaseRepository", "Found ${allPosts.size} total posts")

 // Filter posts to only include those from friends, respecting privacy settings
 val friendPosts = allPosts.filter { post ->
 friendships.contains(post.userId) && // Post is from a friend
 (!post.isPrivate || // Either it's public
 friendships.contains(post.userId)) // Or it's private but from a friend
 }

 // Get shared posts by friends
 val sharedPosts = getSharedPostsForFriends(friendships)
 android.util.Log.d("FirebaseRepository", "Found ${sharedPosts.size} shared posts")

 // Get posts shared by the current user
 val currentUserSharedPosts = getPostsSharedByCurrentUser()
 android.util.Log.d(
 "FirebaseRepository",
 "Found ${currentUserSharedPosts.size} posts shared by current user"
 )

 // Combine regular posts, friends' shared posts, and current user's shared posts
 val combinedPosts =
 (friendPosts + sharedPosts + currentUserSharedPosts).sortedByDescending { it.createdAt }

 android.util.Log.d(
 "FirebaseRepository",
 "Filtered to ${combinedPosts.size} friend posts"
 )

 // Get all likes by current user
 val userLikes = likesCollection
 .whereEqualTo("userId", currentUser.uid)
 .get()
 .await()
 .documents
 .mapNotNull { it.getString("postId") }
 .toSet()

 // Get posts shared by the current user
 val userSharedPosts = sharedPostsCollection
 .whereEqualTo("sharedByUserId", currentUser.uid)
 .get()
 .await()
 .documents
 .mapNotNull { it.getString("originalPostId") }
 .toSet()

 // Mark posts as liked if they are in the userLikes set
 return@withContext combinedPosts.map { post ->
 post.copy(
 isLikedByCurrentUser = userLikes.contains(post.id),
 isSharedByCurrentUser = userSharedPosts.contains(post.id)
 )
 }
 } catch (e: Exception) {
 android.util.Log.e("FirebaseRepository", "Error getting friends' posts", e)
 return@withContext emptyList()
 }
 }

 /**
 * Get posts shared by the current user
 */
 private suspend fun getPostsSharedByCurrentUser(): List<Post> = withContext(Dispatchers.IO) {
 try {
 val currentUser = auth.currentUser ?: return@withContext emptyList<Post>()

 // Get all posts shared by the current user
 val sharedPostDocs = sharedPostsCollection
 .whereEqualTo("sharedByUserId", currentUser.uid)
 .get()
 .await()
 .documents

 if (sharedPostDocs.isEmpty()) {
 return@withContext emptyList<Post>()
 }

 android.util.Log.d(
 "FirebaseRepository",
 "Found ${sharedPostDocs.size} posts shared by current user"
 )

 // Get shared posts by current user
 val userSharedPosts = sharedPostDocs
 .mapNotNull { it.getString("originalPostId") }
 .toSet()

 val result = mutableListOf<Post>()

 for (sharedPostDoc in sharedPostDocs) {
 val sharedPost = sharedPostDoc.toObject(SharedPost::class.java) ?: continue

 android.util.Log.d(
 "FirebaseRepository",
 "Processing post shared by current user: ${sharedPost.id}, original post: ${sharedPost.originalPostId}"
 )

 val originalPostId = sharedPost.originalPostId

 val originalPost = getPostById(originalPostId) ?: continue

 // Create a new post object that combines the original post with sharing info
 val combinedPost = originalPost.copy(
 isSharedPost = true,
 sharedByUserId = sharedPost.sharedByUserId,
 sharedByUserName = sharedPost.sharedByUserName,
 isSharedByCurrentUser = true // Always true since these are shared by current user
 )

 result.add(combinedPost)
 }

 return@withContext result
 } catch (e: Exception) {
 android.util.Log.e(
 "FirebaseRepository",
 "Error getting posts shared by current user",
 e
 )
 return@withContext emptyList<Post>()
 }
 }

 /**
 * Share a post
 */
 suspend fun sharePost(postId: String): Boolean = withContext(Dispatchers.IO) {
 val currentUser = auth.currentUser ?: throw IllegalStateException("No user logged in")

 try {
 // Get the post to share
 val post = getPostById(postId) ?: throw IllegalStateException("Post not found")

 // Check if user has already shared this post
 val existingShareQuery = sharedPostsCollection
 .whereEqualTo("sharedByUserId", currentUser.uid)
 .whereEqualTo("originalPostId", postId)
 .get()
 .await()

 // If already shared, remove the share
 if (!existingShareQuery.isEmpty) {
 android.util.Log.d(
 "FirebaseRepository",
 "Found existing share, removing it"
 )

 val shareDoc = existingShareQuery.documents.first()
 sharedPostsCollection.document(shareDoc.id).delete().await()

 // Decrement the share count on the original post
 postsCollection.document(postId).update("shareCount", FieldValue.increment(-1))
 .await()

 return@withContext false // Indicate share was removed
 }

 // Get current user info
 val user = getCurrentUser() ?: throw IllegalStateException("Failed to get user profile")

 // Create a shared post entry
 val sharedPostId = sharedPostsCollection.document().id
 val sharedPost = SharedPost(
 id = sharedPostId,
 originalPostId = postId,
 sharedByUserId = currentUser.uid,
 sharedByUserName = user.displayName,
 sharedByUserProfilePicture = user.photoUrl,
 createdAt = Timestamp.now()
 )

 // Log the shared post creation
 android.util.Log.d(
 "FirebaseRepository",
 "Creating shared post: $sharedPostId, original: $postId, sharedBy: ${user.displayName}"
 )

 // Save the shared post
 sharedPostsCollection.document(sharedPostId).set(sharedPost).await()

 // Increment the share count on the original post
 postsCollection.document(postId).update("shareCount", FieldValue.increment(1)).await()

 return@withContext true // Indicate share was added
 } catch (e: Exception) {
 android.util.Log.e("FirebaseRepository", "Error sharing post", e)
 return@withContext false
 }
 }

 /**
 * Get shared posts from friends
 */
 private suspend fun getSharedPostsForFriends(friendIds: Set<String>): List<Post> =
 withContext(Dispatchers.IO) {
 try {
 val currentUser = auth.currentUser ?: return@withContext emptyList<Post>()

 // Get all shared posts from friends
 val sharedPostDocs = sharedPostsCollection
 .get()
 .await()
 .documents
 .filter { doc ->
 val sharedByUserId = doc.getString("sharedByUserId")
 friendIds.contains(sharedByUserId)
 }

 if (sharedPostDocs.isEmpty()) {
 return@withContext emptyList<Post>()
 }

 android.util.Log.d(
 "FirebaseRepository",
 "Found ${sharedPostDocs.size} shared post documents"
 )

 // Get shared posts by current user
 val userSharedPosts = sharedPostsCollection
 .whereEqualTo("sharedByUserId", currentUser.uid)
 .get()
 .await()
 .documents
 .mapNotNull { it.getString("originalPostId") }
 .toSet()

 android.util.Log.d(
 "FirebaseRepository",
 "Current user has shared ${userSharedPosts.size} posts: $userSharedPosts"
 )

 // Get original posts for each shared post
 val result = mutableListOf<Post>()

 for (sharedPostDoc in sharedPostDocs) {
 val sharedPost = sharedPostDoc.toObject(SharedPost::class.java) ?: continue

 android.util.Log.d(
 "FirebaseRepository",
 "Processing shared post: ${sharedPost.id}, original post: ${sharedPost.originalPostId}"
 )

 val originalPostId = sharedPost.originalPostId

 val originalPost = getPostById(originalPostId) ?: continue

 // Create a new post object that combines the original post with sharing info
 val combinedPost = originalPost.copy(
 isSharedPost = true,
 sharedByUserId = sharedPost.sharedByUserId,
 sharedByUserName = sharedPost.sharedByUserName,
 isSharedByCurrentUser = userSharedPosts.contains(originalPostId)
 )

 android.util.Log.d(
 "FirebaseRepository",
 "Added shared post with sharer: ${sharedPost.sharedByUserName}, isSharedByCurrentUser=${
 userSharedPosts.contains(
 originalPostId
 )
 }"
 )

 result.add(combinedPost)
 }

 return@withContext result
 } catch (e: Exception) {
 android.util.Log.e("FirebaseRepository", "Error getting shared posts", e)
 return@withContext emptyList<Post>()
 }
 }

 // Search for posts by content
 suspend fun searchPosts(query: String): List<Post> = withContext(Dispatchers.IO) {
 if (query.length < 2) return@withContext emptyList()

 val currentUser = auth.currentUser ?: return@withContext emptyList()

 // Save search query to history if it's not empty
 if (query.isNotEmpty()) {
 try {
 saveSearchQuery(query)
 } catch (e: Exception) {
 Log.e("FirebaseRepository", "Error saving search query: ${e.message}", e)
 }
 }

 try {
 // Get all posts
 val allPosts = postsCollection
 .get()
 .await()
 .toObjects(Post::class.java)
 .sortedByDescending { it.createdAt }

 // Get all likes by current user
 val userLikes = likesCollection
 .whereEqualTo("userId", currentUser.uid)
 .get()
 .await()
 .documents
 .mapNotNull { it.getString("postId") }
 .toSet()

 // Get user's friends to filter private posts
 val friendships = friendshipsCollection
 .whereEqualTo("userId", currentUser.uid)
 .whereEqualTo("status", "ACCEPTED")
 .get()
 .await()
 .documents
 .mapNotNull { it.getString("friendId") }
 .toSet()

 // Filter posts based on:
 // 1. Post text contains query (case insensitive)
 // 2. Privacy settings (same as in getPostsWithLikeStatus)
 val filteredPosts = allPosts.filter { post ->
 post.text.contains(query, ignoreCase = true) &&
 (!post.isPrivate || post.userId == currentUser.uid || friendships.contains(
 post.userId
 ))
 }

 // Mark posts as liked if they are in the userLikes set
 return@withContext filteredPosts.map { post ->
 post.copy(isLikedByCurrentUser = userLikes.contains(post.id))
 }
 } catch (e: Exception) {
 Log.e("FirebaseRepository", "Error searching posts: ${e.message}", e)
 return@withContext emptyList()
 }
 }

 // Comment operations
 suspend fun addComment(postId: String, text: String, imageUri: Uri?): Comment = withContext(Dispatchers.IO) {
 val currentUser = auth.currentUser ?: throw IllegalStateException("No user logged in")

 // Get the user display name
 val userDisplayName = currentUser.displayName ?: "Unknown User"

 // If image is included, try to upload to storage first
 var imageUrl: String? = null
 if (imageUri != null) {
 try {
 imageUrl = uploadImage(imageUri, "comments")
 } catch (e: Exception) {
 // Log the error but continue creating comment without image
 android.util.Log.e(
 "FirebaseRepository",
 "Failed to upload comment image: ${e.message}"
 )
 // If image upload fails, we'll proceed with creating the comment without an image
 }
 }

 val commentId = commentsCollection.document().id
 val comment = Comment(
 id = commentId,
 postId = postId,
 userId = currentUser.uid,
 userDisplayName = userDisplayName, 
 text = text,
 imageUrl = imageUrl,
 createdAt = Timestamp.now()
 )

 commentsCollection.document(commentId).set(comment).await()

 // Increment comment count
 postsCollection.document(postId).update("commentCount",
 FieldValue.increment(1)).await()

 // Create notification for the comment
 val post = getPostById(postId) ?: return@withContext comment
 val user = getCurrentUser() ?: return@withContext comment
 if (post.userId != user.id) {
 notificationRepository.createCommentNotification(post, commentId, user)
 } else {
 Log.d("FirebaseRepository", "Skipping self-notification for comment")
 }

 comment
 }

 /**
 * Add a comment with a provided Cloudinary image URL
 */
 suspend fun addCommentWithImageUrl(postId: String, text: String, imageUrl: String?): Comment =
 withContext(Dispatchers.IO) {
 val currentUser = auth.currentUser ?: throw IllegalStateException("No user logged in")

 // Get the user display name
 val userDisplayName = currentUser.displayName ?: "Unknown User"

 val commentId = commentsCollection.document().id
 val comment = Comment(
 id = commentId,
 postId = postId,
 userId = currentUser.uid,
 userDisplayName = userDisplayName,
 text = text,
 imageUrl = imageUrl,
 createdAt = Timestamp.now()
 )

 commentsCollection.document(commentId).set(comment).await()

 // Increment comment count
 postsCollection.document(postId).update(
 "commentCount",
 FieldValue.increment(1)
 ).await()

 // Create notification for the comment
 val post = getPostById(postId) ?: return@withContext comment
 val user = getCurrentUser() ?: return@withContext comment
 if (post.userId != user.id) {
 notificationRepository.createCommentNotification(post, commentId, user)
 } else {
 Log.d("FirebaseRepository", "Skipping self-notification for comment")
 }

 comment
 }

 /**
 * Add a comment with a provided Cloudinary media URL (image or video)
 */
 suspend fun addCommentWithMediaUrl(
 postId: String,
 text: String,
 mediaUrl: String?,
 isVideo: Boolean = false
 ): Comment =
 withContext(Dispatchers.IO) {
 val currentUser = auth.currentUser ?: throw IllegalStateException("No user logged in")

 // Get the user display name
 val userDisplayName = currentUser.displayName ?: "Unknown User"

 val commentId = commentsCollection.document().id
 val comment = if (isVideo) {
 Comment(
 id = commentId,
 postId = postId,
 userId = currentUser.uid,
 userDisplayName = userDisplayName,
 text = text,
 videoUrl = mediaUrl,
 hasVideo = true,
 createdAt = Timestamp.now()
 )
 } else {
 Comment(
 id = commentId,
 postId = postId,
 userId = currentUser.uid,
 userDisplayName = userDisplayName,
 text = text,
 imageUrl = mediaUrl,
 createdAt = Timestamp.now()
 )
 }

 commentsCollection.document(commentId).set(comment).await()

 // Increment comment count
 postsCollection.document(postId).update(
 "commentCount",
 FieldValue.increment(1)
 ).await()

 // Create notification for the comment
 val post = getPostById(postId) ?: return@withContext comment
 val user = getCurrentUser() ?: return@withContext comment
 if (post.userId != user.id) {
 notificationRepository.createCommentNotification(post, commentId, user)
 } else {
 Log.d("FirebaseRepository", "Skipping self-notification for comment")
 }

 comment
 }

 suspend fun getCommentsForPost(postId: String): List<Comment> = withContext(Dispatchers.IO) {
 try {
 commentsCollection
 .whereEqualTo("postId", postId)
 .get()
 .await()
 .toObjects(Comment::class.java)
 .sortedBy { it.createdAt }
 } catch (e: Exception) {
 // Fallback to a simpler query if index not available
 commentsCollection
 .get()
 .await()
 .toObjects(Comment::class.java)
 .filter { it.postId == postId }
 .sortedBy { it.createdAt }
 }
 }

 suspend fun getPostById(postId: String): Post? = withContext(Dispatchers.IO) {
 val postDoc = postsCollection.document(postId).get().await()
 val post = postDoc.toObject(Post::class.java)

 // Debug output
 if (post != null) {
 Log.d("FirebaseRepository",
 "Retrieved post: id=${post.id}, userId=${post.userId}, text=${post.text}")

 // Check if post is shared by the current user
 val currentUser = auth.currentUser
 if (currentUser != null) {
 val sharedPostQuery = sharedPostsCollection
 .whereEqualTo("sharedByUserId", currentUser.uid)
 .whereEqualTo("originalPostId", postId)
 .get()
 .await()

 val isSharedByUser = !sharedPostQuery.isEmpty()

 Log.d(
 "FirebaseRepository",
 "Post $postId isSharedByCurrentUser=$isSharedByUser"
 )

 return@withContext post.copy(isSharedByCurrentUser = isSharedByUser)
 }
 } else {
 Log.e("FirebaseRepository", "Post was null for id: $postId")
 }

 return@withContext post
 }

 // Like operations
 suspend fun toggleLike(postId: String): Boolean = withContext(Dispatchers.IO) {
 val currentUser = auth.currentUser ?: throw IllegalStateException("No user logged in")

 val likeQuery = likesCollection
 .whereEqualTo("postId", postId)
 .whereEqualTo("userId", currentUser.uid)
 .get()
 .await()

 if (likeQuery.isEmpty) {
 // Add like
 val likeId = likesCollection.document().id
 val likeData = hashMapOf(
 "id" to likeId,
 "postId" to postId,
 "userId" to currentUser.uid,
 "createdAt" to Timestamp.now()
 )

 likesCollection.document(likeId).set(likeData).await()
 postsCollection.document(postId).update("likeCount",
 FieldValue.increment(1)).await()

 // Create notification for the like
 val post = getPostById(postId) ?: return@withContext true
 val user = getCurrentUser() ?: return@withContext true
 if (post.userId != user.id) {
 notificationRepository.createLikeNotification(post, user)
 } else {
 Log.d("FirebaseRepository", "Skipping self-notification for like")
 }

 true
 } else {
 // Remove like
 val likeDoc = likeQuery.documents.first()
 likesCollection.document(likeDoc.id).delete().await()
 postsCollection.document(postId).update("likeCount",
 FieldValue.increment(-1)).await()
 false
 }
 }

 // Comment like operations
 suspend fun toggleCommentLike(commentId: String): Boolean = withContext(Dispatchers.IO) {
 val currentUser = auth.currentUser ?: throw IllegalStateException("No user logged in")

 val likeQuery = commentLikesCollection
 .whereEqualTo("commentId", commentId)
 .whereEqualTo("userId", currentUser.uid)
 .get()
 .await()

 if (likeQuery.isEmpty) {
 // Add like
 val likeId = commentLikesCollection.document().id
 val likeData = hashMapOf(
 "id" to likeId,
 "commentId" to commentId,
 "userId" to currentUser.uid,
 "userDisplayName" to (currentUser.displayName ?: "Unknown User"),
 "createdAt" to Timestamp.now()
 )

 commentLikesCollection.document(likeId).set(likeData).await()
 commentsCollection.document(commentId).update("likeCount",
 FieldValue.increment(1)).await()
 true
 } else {
 // Remove like
 val likeDoc = likeQuery.documents.first()
 commentLikesCollection.document(likeDoc.id).delete().await()
 commentsCollection.document(commentId).update("likeCount",
 FieldValue.increment(-1)).await()
 false
 }
 }

 // Add a reply to a comment
 suspend fun addReply(parentCommentId: String, text: String, imageUri: Uri?): Comment = withContext(Dispatchers.IO) {
 val currentUser = auth.currentUser ?: throw IllegalStateException("No user logged in")
 val userDisplayName = currentUser.displayName ?: "Unknown User"

 // Get parent comment to find the post
 val parentComment = commentsCollection.document(parentCommentId).get().await()
 .toObject(Comment::class.java) ?: throw IllegalStateException("Parent comment not found")

 // If image is included, try to upload to storage first
 var imageUrl: String? = null
 if (imageUri != null) {
 try {
 imageUrl = uploadImage(imageUri, "comments")
 } catch (e: Exception) {
 // Log the error but continue creating reply without image
 android.util.Log.e(
 "FirebaseRepository",
 "Failed to upload reply image: ${e.message}"
 )
 // If image upload fails, we'll proceed with creating the reply without an image
 }
 }

 val commentId = commentsCollection.document().id
 val reply = Comment(
 id = commentId,
 postId = parentComment.postId, // Same post as parent
 userId = currentUser.uid,
 userDisplayName = userDisplayName,
 text = text,
 imageUrl = imageUrl,
 createdAt = Timestamp.now(),
 parentCommentId = parentCommentId // Mark as a reply
 )

 commentsCollection.document(commentId).set(reply).await()

 // Increment reply count on parent comment
 commentsCollection.document(parentCommentId).update("replyCount",
 FieldValue.increment(1)).await()

 reply
 }

