package com.example.kiendatn2.repository

import com.example.kiendatn2.data.FirebaseNotification
import com.example.kiendatn2.data.Notification
import com.example.kiendatn2.data.NotificationType
import com.example.kiendatn2.data.Post
import com.example.kiendatn2.data.User
import com.example.kiendatn2.data.toFirebaseNotification
import com.google.firebase.firestore.FirebaseFirestore
import kotlinx.coroutines.tasks.await
import kotlinx.coroutines.flow.Flow
import com.google.firebase.firestore.Query
import kotlinx.coroutines.channels.awaitClose
import kotlinx.coroutines.flow.callbackFlow
import android.util.Log
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import com.google.firebase.auth.FirebaseAuth

class NotificationRepository {
 private val firestore = FirebaseFirestore.getInstance()
 private val auth = FirebaseAuth.getInstance()

 // Create a notification when someone likes a post
 suspend fun createLikeNotification(post: Post, currentUser: User) {
 // Add debug logging
 Log.d("NotificationRepository", 
 "Creating like notification: postUserId=${post.userId}, currentUserId=${currentUser.id}, isSelf=${post.userId == currentUser.id}")

 // Explicitly return if it's self-interaction
 if (post.userId == currentUser.id) {
 Log.d("NotificationRepository", "Skipping self-notification for like")
 return
 }

 val notificationId = firestore.collection("notifications").document().id

 // Create the app notification object
 val notification = Notification(
 id = notificationId,
 recipientId = post.userId,
 senderId = currentUser.id,
 senderName = currentUser.displayName,
 senderProfileImageUrl = currentUser.photoUrl ?: "",
 type = NotificationType.LIKE,
 postId = post.id,
 isRead = false
 )

 // Convert to Firebase notification
 val firebaseNotification = notification.toFirebaseNotification()

 // Store in Firestore
 firestore.collection("notifications")
 .document(notificationId)
 .set(firebaseNotification)
 .await()

 Log.d("NotificationRepository", "Notification created with id: ${notification.id}")
 }

 // Create a notification when someone comments on a post
 suspend fun createCommentNotification(post: Post, commentId: String, currentUser: User) {
 // Add debug logging
 Log.d("NotificationRepository", 
 "Creating comment notification: postUserId=${post.userId}, currentUserId=${currentUser.id}, isSelf=${post.userId == currentUser.id}")

 // Explicitly return if it's self-interaction
 if (post.userId == currentUser.id) {
 Log.d("NotificationRepository", "Skipping self-notification for comment")
 return
 }

 val notificationId = firestore.collection("notifications").document().id

 // Create the app notification object
 val notification = Notification(
 id = notificationId,
 recipientId = post.userId,
 senderId = currentUser.id,
 senderName = currentUser.displayName,
 senderProfileImageUrl = currentUser.photoUrl ?: "",
 type = NotificationType.COMMENT,
 postId = post.id,
 commentId = commentId,
 isRead = false
 )

 // Convert to Firebase notification
 val firebaseNotification = notification.toFirebaseNotification()

 // Store in Firestore
 firestore.collection("notifications")
 .document(notificationId)
 .set(firebaseNotification)
 .await()

 Log.d("NotificationRepository", "Notification created with id: ${notification.id}")
 }

 // Create a notification when someone sends a friend request
 suspend fun createFriendRequestNotification(recipientId: String, currentUser: User) {
 Log.d(
 "NotificationRepository",
 "Creating friend request notification: recipientId=${recipientId}, senderId=${currentUser.id}"
 )

 val notificationId = firestore.collection("notifications").document().id

 // Create the app notification object
 val notification = Notification(
 id = notificationId,
 recipientId = recipientId,
 senderId = currentUser.id,
 senderName = currentUser.displayName,
 senderProfileImageUrl = currentUser.photoUrl ?: "",
 type = NotificationType.FRIEND_REQUEST,
 isRead = false
 )

 // Convert to Firebase notification
 val firebaseNotification = notification.toFirebaseNotification()

 // Store in Firestore
 firestore.collection("notifications")
 .document(notificationId)
 .set(firebaseNotification)
 .await()

 Log.d(
 "NotificationRepository",
 "Friend request notification created with id: ${notification.id}"
 )
 }

 // Create a notification when someone accepts a friend request
 suspend fun createFriendAcceptedNotification(recipientId: String, currentUser: User) {
 Log.d(
 "NotificationRepository",
 "Creating friend accepted notification: recipientId=${recipientId}, senderId=${currentUser.id}"
 )

 val notificationId = firestore.collection("notifications").document().id

 // Create the app notification object
 val notification = Notification(
 id = notificationId,
 recipientId = recipientId,
 senderId = currentUser.id,
 senderName = currentUser.displayName,
 senderProfileImageUrl = currentUser.photoUrl ?: "",
 type = NotificationType.FRIEND_ACCEPTED,
 isRead = false
 )

 // Convert to Firebase notification
 val firebaseNotification = notification.toFirebaseNotification()

 // Store in Firestore
 firestore.collection("notifications")
 .document(notificationId)
 .set(firebaseNotification)
 .await()

 Log.d(
 "NotificationRepository",
 "Friend accepted notification created with id: ${notification.id}"
 )
 }

 // Get notifications for a user
 fun getNotificationsForUser(userId: String): Flow<List<Notification>> = callbackFlow {
 val listenerRegistration = firestore.collection("notifications")
 .whereEqualTo("recipientId", userId)
 .orderBy("timestamp", Query.Direction.DESCENDING)
 .addSnapshotListener { snapshot, error ->
 if (error != null) {
 close(error)
 return@addSnapshotListener
 }

 val notifications = snapshot?.documents?.mapNotNull { doc ->
 try {
 // Convert Firebase notification to app notification
 val firebaseNotification = doc.toObject(FirebaseNotification::class.java)
 firebaseNotification?.toNotification()
 } catch (e: Exception) {
 Log.e(
 "NotificationRepository",
 "Error converting notification: ${e.message}"
 )
 null
 }
 }?.filter { 
 // Filter out any case where senderId == recipientId (self-notifications)
 it.senderId != it.recipientId 
 } ?: listOf()

 trySend(notifications)
 }

 awaitClose { listenerRegistration.remove() }
 }

 // Mark a notification as read
 suspend fun markNotificationAsRead(notificationId: String) {
 // Update just the read field in Firebase
 firestore.collection("notifications")
 .document(notificationId)
 .update("read", true)
 .await()
 }

 // Mark all notifications for a user as read
 suspend fun markAllNotificationsAsRead(userId: String) {
 val batch = firestore.batch()

 // Get all unread notifications
 val notificationDocs = firestore.collection("notifications")
 .whereEqualTo("recipientId", userId)
 .whereEqualTo("read", false)
 .get()
 .await()

 // Update the read field for each notification
 for (doc in notificationDocs.documents) {
 batch.update(doc.reference, "read", true)
 }

 // Only commit if there are changes to make
 if (notificationDocs.size() > 0) {
 batch.commit().await()
 }
 }

 // Add debug method to directly check for self-notifications
 suspend fun checkSelfNotifications() = withContext(Dispatchers.IO) {
 try {
 val currentUser = getCurrentUser() ?: return@withContext

 // Check for self-notifications
 val notifications = firestore.collection("notifications")
 .whereEqualTo("recipientId", currentUser.id)
 .whereEqualTo("senderId", currentUser.id)
 .get()
 .await()

 if (!notifications.isEmpty) {
 Log.e("FirebaseRepository", 
 "Found ${notifications.size()} self-notifications for user ${currentUser.id}")

 // Optional: clean up existing self-notifications
 val batch = firestore.batch()
 for (doc in notifications.documents) {
 batch.delete(doc.reference)
 }
 batch.commit()
 } else {
 Log.d("FirebaseRepository", "No self-notifications found")
 }
 } catch (e: Exception) {
 Log.e("FirebaseRepository", "Error checking self-notifications: ${e.message}")
 }
 }

 private suspend fun getCurrentUser(): User? {
 try {
 val firebaseUser = auth.currentUser ?: return null

 val userDoc = firestore.collection("users").document(firebaseUser.uid).get().await()
 if (!userDoc.exists()) {
 return null
 }

 return userDoc.toObject(User::class.java)
 ?.copy(id = firebaseUser.uid, uid = firebaseUser.uid)
 } catch (e: Exception) {
 Log.e("NotificationRepository", "Error getting current user: ${e.message}")
 return null
 }
 }
}
