// Create a new file with Firestore security rules
rules_version = '2';

service cloud.firestore {
 match /databases/{database}/documents {
 // User profiles
 match /users/{userId} {
 allow read: if true; // Anyone can read user profiles
 allow write: if request.auth != null && request.auth.uid == userId; // Only own profile
 }

 // Posts
 match /posts/{postId} {
 allow read: if true; // Anyone can read posts
 allow create: if request.auth != null; // Logged in users can create posts
 allow update, delete: if request.auth != null && request.auth.uid == resource.data.userId; // Own posts only
 }

 // Comments
 match /comments/{commentId} {
 allow read: if true;
 allow create: if request.auth != null;
 allow update, delete: if request.auth != null && request.auth.uid == resource.data.userId;
 }

 // Likes
 match /likes/{likeId} {
 allow read: if true;
 allow create, delete: if request.auth != null;
 }

 // Comment likes
 match /commentLikes/{likeId} {
 allow read: if true;
 allow create, delete: if request.auth != null;
 }

 // Friendships
 match /friendships/{friendshipId} {
 allow read: if request.auth != null;
 allow create: if request.auth != null && request.resource.data.senderId == request.auth.uid;
 allow update: if request.auth != null && 
 (resource.data.senderId == request.auth.uid || resource.data.receiverId == request.auth.uid);
 allow delete: if request.auth != null && 
 (resource.data.senderId == request.auth.uid || resource.data.receiverId == request.auth.uid);
 }

 // Notifications
 match /notifications/{notificationId} {
 allow read: if request.auth != null && request.auth.uid == resource.data.recipientId;
 allow create: if request.auth != null;
 allow update: if request.auth != null && request.auth.uid == resource.data.recipientId;
 allow delete: if request.auth != null && 
 (request.auth.uid == resource.data.recipientId || request.auth.uid == resource.data.senderId);
 }
 }
}
