 /**
 * Create a post with a provided Cloudinary media URL (image or video)
 */
 suspend fun createPostWithMediaUrl(
 text: String,
 mediaUrl: String?,
 isVideo: Boolean = false
 ): Post =
 withContext(Dispatchers.IO) {
