 // Search history methods
 suspend fun saveSearchQuery(query: String) = withContext(Dispatchers.IO) {
 val currentUser = auth.currentUser ?: return@withContext

 try {
 val searchHistoryId = searchHistoryCollection.document().id
 val searchHistory = hashMapOf(
 "id" to searchHistoryId,
 "userId" to currentUser.uid,
 "query" to query,
 "timestamp" to Timestamp.now()
 )

 searchHistoryCollection.document(searchHistoryId).set(searchHistory).await()
 Log.d("FirebaseRepository", "Search query saved: $query")
 } catch (e: Exception) {
 Log.e("FirebaseRepository", "Error saving search query: ${e.message}", e)
 }
 }

 suspend fun getSearchHistory(limit: Int = 10): List<SearchHistory> =
 withContext(Dispatchers.IO) {
 val currentUser = auth.currentUser ?: return@withContext emptyList()

 try {
 return@withContext searchHistoryCollection
 .whereEqualTo("userId", currentUser.uid)
 .orderBy("timestamp", Query.Direction.DESCENDING)
 .limit(limit.toLong())
 .get()
 .await()
 .toObjects(SearchHistory::class.java)
 } catch (e: Exception) {
 Log.e("FirebaseRepository", "Error getting search history: ${e.message}", e)
 return@withContext emptyList()
 }
 }

 suspend fun deleteSearchHistoryItem(historyId: String) = withContext(Dispatchers.IO) {
 try {
 searchHistoryCollection.document(historyId).delete().await()
 Log.d("FirebaseRepository", "Search history item deleted: $historyId")
 } catch (e: Exception) {
 Log.e("FirebaseRepository", "Error deleting search history item: ${e.message}", e)
 }
 }

 suspend fun clearSearchHistory() = withContext(Dispatchers.IO) {
 val currentUser = auth.currentUser ?: return@withContext

 try {
 val batch = firestore.batch()
 val historyItems = searchHistoryCollection
 .whereEqualTo("userId", currentUser.uid)
 .get()
 .await()

 for (item in historyItems) {
 batch.delete(item.reference)
 }

 batch.commit().await()
 Log.d("FirebaseRepository", "Search history cleared for user: ${currentUser.uid}")
 } catch (e: Exception) {
 Log.e("FirebaseRepository", "Error clearing search history: ${e.message}", e)
 }
 }

 // Add method to check for self-notifications
 suspend fun checkSelfNotifications() = withContext(Dispatchers.IO) {
 try {
 val currentUser = getCurrentUser() ?: return@withContext

 // Check for self-notifications
 val notifications = firestore.collection("notifications")
 .whereEqualTo("recipientId", currentUser.id)
 .whereEqualTo("senderId", currentUser.id)
 .get()
 .await()

 if (!notifications.isEmpty) {
 android.util.Log.e("FirebaseRepository", 
 "Found ${notifications.size()} self-notifications for user ${currentUser.id}")

 // Optional: clean up existing self-notifications
 val batch = firestore.batch()
 for (doc in notifications.documents) {
 batch.delete(doc.reference)
 }
 batch.commit()
 } else {
 android.util.Log.d("FirebaseRepository", "No self-notifications found")
 }
 } catch (e: Exception) {
 android.util.Log.e("FirebaseRepository", "Error checking self-notifications: ${e.message}")
 }
 }

 // Debug method to check for friendships in Firebase
 suspend fun debugFriendships() = withContext(Dispatchers.IO) {
 val currentUser = auth.currentUser ?: return@withContext

 try {
 // Log the current user ID for reference
 android.util.Log.d("FirebaseRepository", "Current user ID: ${currentUser.uid}")

 // Check friendships collection structure
 val allFriendships = friendshipsCollection.get().await()
 android.util.Log.d(
 "FirebaseRepository",
 "Total friendships in collection: ${allFriendships.size()}"
 )

 // Check if there are any friendships where current user is sender
 val senderFriendships = friendshipsCollection
 .whereEqualTo("senderId", currentUser.uid)
 .get()
 .await()
 android.util.Log.d(
 "FirebaseRepository",
 "Friendships where user is sender: ${senderFriendships.size()}"
 )

 // Check if there are any friendships where current user is receiver
 val receiverFriendships = friendshipsCollection
 .whereEqualTo("receiverId", currentUser.uid)
 .get()
 .await()
 android.util.Log.d(
 "FirebaseRepository",
 "Friendships where user is receiver: ${receiverFriendships.size()}"
 )

 // Check specifically for ACCEPTED friendships
 val acceptedSenderFriendships = friendshipsCollection
 .whereEqualTo("senderId", currentUser.uid)
 .whereEqualTo("status", "ACCEPTED")
 .get()
 .await()
 android.util.Log.d(
 "FirebaseRepository",
 "ACCEPTED friendships where user is sender: ${acceptedSenderFriendships.size()}"
 )

 val acceptedReceiverFriendships = friendshipsCollection
 .whereEqualTo("receiverId", currentUser.uid)
 .whereEqualTo("status", "ACCEPTED")
 .get()
 .await()
 android.util.Log.d(
 "FirebaseRepository",
 "ACCEPTED friendships where user is receiver: ${acceptedReceiverFriendships.size()}"
 )

 // List friend IDs to verify
 val friendIds = mutableSetOf<String>()

 acceptedSenderFriendships.forEach { doc ->
 val receiverId = doc.getString("receiverId")
 if (receiverId != null) friendIds.add(receiverId)
 android.util.Log.d("FirebaseRepository", "Friend (receiver): $receiverId")
 }

 acceptedReceiverFriendships.forEach { doc ->
 val senderId = doc.getString("senderId")
 if (senderId != null) friendIds.add(senderId)
 android.util.Log.d("FirebaseRepository", "Friend (sender): $senderId")
 }

 android.util.Log.d(
 "FirebaseRepository",
 "Total unique friends found: ${friendIds.size}"
 )
 } catch (e: Exception) {
 android.util.Log.e("FirebaseRepository", "Error debugging friendships: ${e.message}", e)
 }
 }
}
